contracts/TestToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestToken: a plain ERC-20 for the ZETAPHY testnet DEX (no value, testnet only).
/// @notice The deployer gets the initial supply and may mint more (a test faucet).
///         Optional `feeBps`: a cut of every transfer is burned (fee-on-transfer
///         token, to test the router's *SupportingFeeOnTransferTokens functions).
contract TestToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    uint16 public immutable feeBps;
    address public immutable minter;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    error InsufficientBalance();
    error InsufficientAllowance();
    error NotMinter();

    constructor(string memory name_, string memory symbol_, uint8 decimals_, uint256 initialSupply, uint16 feeBps_) {
        require(feeBps_ <= 5000, "fee");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        feeBps = feeBps_;
        minter = msg.sender;
        _mint(msg.sender, initialSupply);
    }

    function mint(address to, uint256 value) external {
        if (msg.sender != minter) revert NotMinter();
        _mint(to, value);
    }

    function _mint(address to, uint256 value) private {
        totalSupply += value;
        unchecked { balanceOf[to] += value; }
        emit Transfer(address(0), to, value);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - value; }
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        uint256 b = balanceOf[from];
        if (b < value) revert InsufficientBalance();
        uint256 fee = (value * feeBps) / 10_000;
        unchecked {
            balanceOf[from] = b - value;
            balanceOf[to] += value - fee;
            totalSupply -= fee;
        }
        emit Transfer(from, to, value - fee);
        if (fee != 0) emit Transfer(from, address(0), fee);
    }
}

contracts/WZETAPHY.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WZETAPHY: wrapped native coin, one token per wei (a classic WETH, written from scratch).
/// @notice On ZETAPHY itself the DEX uses the native ERC-20 precompile
///         0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE instead (Cosmos EVM's WERC20,
///         whose balances ARE the native balances). This contract is for the
///         unit tests (an EVM without that precompile) and for other EVM chains:
///         `cli.js deploy --wnative deploy` deploys it.
contract WZETAPHY {
    string public constant name = "Wrapped ZETAPHY";
    string public constant symbol = "WZTPHY";
    uint8 public constant decimals = 18;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Deposit(address indexed to, uint256 value);
    event Withdrawal(address indexed from, uint256 value);

    error InsufficientBalance();
    error InsufficientAllowance();
    error SendFailed();

    receive() external payable {
        deposit();
    }

    function deposit() public payable {
        balanceOf[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw(uint256 value) external {
        if (balanceOf[msg.sender] < value) revert InsufficientBalance();
        unchecked { balanceOf[msg.sender] -= value; }
        emit Withdrawal(msg.sender, value);
        (bool ok,) = msg.sender.call{value: value}("");
        if (!ok) revert SendFailed();
    }

    function totalSupply() external view returns (uint256) {
        return address(this).balance;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        return transferFrom(msg.sender, to, value);
    }

    function transferFrom(address from, address to, uint256 value) public returns (bool) {
        if (balanceOf[from] < value) revert InsufficientBalance();
        if (from != msg.sender) {
            uint256 a = allowance[from][msg.sender];
            if (a != type(uint256).max) {
                if (a < value) revert InsufficientAllowance();
                unchecked { allowance[from][msg.sender] = a - value; }
            }
        }
        unchecked {
            balanceOf[from] -= value;
            balanceOf[to] += value;
        }
        emit Transfer(from, to, value);
        return true;
    }
}

contracts/ZetaphyFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ZetaphyPair} from "./ZetaphyPair.sol";

/// The part of Neuro's ThreatRegistry (zetaphy-network/contracts/ThreatRegistry.sol)
/// the DEX reads: true once a flag on the contract's address on this chain, or
/// on its exact code (extcodehash), is enforced. Reason: ThreatRegistry.Reason.
interface IThreatRegistryView {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

/// @title ZetaphyFactory: creates one ZetaphyPair per token pair (CREATE2) and
///        holds the DEX's governance settings.
/// @notice Governance (a multisig on the testnet) may:
///           - setFeeTo(a):           the protocol fee switch. Zero (the default) = off;
///                                    otherwise 1/6 of the 0.3% LP fee goes to `a` as LP tokens;
///           - setThreatRegistry(r):  Neuro's ThreatRegistry. Zero (the default) = off;
///                                    otherwise the router refuses to swap into, or add
///                                    liquidity with, a token whose flag is ENFORCED there.
///                                    Selling a token for the native coin and removing
///                                    liquidity never ask the registry, so they always work;
///           - sweep the router's stray native coins (ZetaphyRouter.sweep; never user funds);
///           - transfer governance (two steps: setGovernance, then acceptGovernance).
///         Governance cannot move anyone's funds, change the 0.3% fee, or stop the
///         pairs themselves (they never ask the registry). It CAN stop buying through
///         the router: the router's registry check fails closed, so a registry that
///         stops answering (or that answers "enforced" for every token) makes the
///         router refuse every swap into a token and every add of liquidity until
///         governance sets the registry to zero (which lifts it at once). The check
///         here (setThreatRegistry) only proves the registry answered when it was set.
contract ZetaphyFactory {
    address public governance;
    address public pendingGovernance;
    address public feeTo;
    address public threatRegistry;

    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;

    /// keccak256 of ZetaphyPair's creation code: pair = CREATE2(this, keccak256(token0, token1), PAIR_CODE_HASH).
    bytes32 public immutable PAIR_CODE_HASH;

    address private _p0;
    address private _p1;

    event PairCreated(address indexed token0, address indexed token1, address pair, uint256 allPairsLength);
    event FeeToSet(address feeTo);
    event ThreatRegistrySet(address registry);
    event GovernanceProposed(address governance);
    event GovernanceSet(address governance);

    error IdenticalAddresses();
    error ZeroAddress();
    error PairExists();
    error NotGovernance();
    error NotPendingGovernance();
    error NotARegistry();

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
        PAIR_CODE_HASH = keccak256(type(ZetaphyPair).creationCode);
        emit GovernanceSet(governance_);
    }

    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    /// Read by a new pair's constructor (only set during createPair).
    function pairParameters() external view returns (address token0, address token1) {
        return (_p0, _p1);
    }

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert ZeroAddress();
        if (getPair[token0][token1] != address(0)) revert PairExists();
        _p0 = token0;
        _p1 = token1;
        pair = address(new ZetaphyPair{salt: keccak256(abi.encodePacked(token0, token1))}());
        delete _p0;
        delete _p1;
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair;
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);
    }

    function setFeeTo(address feeTo_) external onlyGov {
        feeTo = feeTo_;
        emit FeeToSet(feeTo_);
    }

    /// Gas for the query below; the same cap as ZetaphyRouter.REGISTRY_GAS.
    uint256 public constant REGISTRY_GAS = 100_000;

    /// Zero switches the router's check off. A nonzero address must answer
    /// isContractEnforced within REGISTRY_GAS (checked here), so a typo cannot
    /// stop every swap. It cannot prove the registry keeps answering later.
    function setThreatRegistry(address registry) external onlyGov {
        if (registry != address(0)) {
            (bool ok, bytes memory r) = registry.staticcall{gas: REGISTRY_GAS}(abi.encodeCall(IThreatRegistryView.isContractEnforced, (address(this))));
            if (!ok || r.length < 64) revert NotARegistry();
        }
        threatRegistry = registry;
        emit ThreatRegistrySet(registry);
    }

    function setGovernance(address next) external onlyGov {
        pendingGovernance = next;
        emit GovernanceProposed(next);
    }

    function acceptGovernance() external {
        if (msg.sender != pendingGovernance) revert NotPendingGovernance();
        governance = msg.sender;
        pendingGovernance = address(0);
        emit GovernanceSet(msg.sender);
    }
}

contracts/ZetaphyPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY DEX pair: a constant-product (x * y = k) pool of two tokens, written
// from scratch for ZETAPHY (MIT). The math and the interface follow the
// Uniswap V2 whitepaper (https://uniswap.org/whitepaper.pdf) so that tools
// that know V2 pools read it too, but no Uniswap source code is copied.
//
//   - fee: 0.3% of every input stays in the pool (LP fee);
//   - protocol fee: off by default. When governance sets factory.feeTo, 1/6
//     of the fee growth (0.05% of volume) is minted to feeTo as LP tokens,
//     on the next mint/burn (whitepaper section 2.4);
//   - TWAP: price0CumulativeLast / price1CumulativeLast accumulate the
//     UQ112.112 price times seconds, at the first touch of each block, before
//     the trade (overflow is intended: consumers take differences);
//   - MINIMUM_LIQUIDITY (1000 wei of LP) is locked at address(0) on the first
//     mint, so the share price can never be pushed to a level where nobody
//     can afford a share;
//   - every state-changing function holds one reentrancy lock;
//   - skim() sends out tokens above the reserves, sync() sets the reserves
//     to the balances;
//   - flash swaps: swap() sends the output first and, with data, calls
//     zetaphyDexCall on `to`; the K check after it needs the input (or the
//     output back plus the fee) to be in the pool by then.

interface IZetaphyFactoryForPair {
    function feeTo() external view returns (address);
    function pairParameters() external view returns (address token0, address token1);
}

interface IERC20Balance {
    function balanceOf(address) external view returns (uint256);
}

interface IZetaphyDexCallee {
    function zetaphyDexCall(address sender, uint256 amount0Out, uint256 amount1Out, bytes calldata data) external;
}

contract ZetaphyPair {
    // ---- LP token (ERC-20) ----
    string public constant name = "ZETAPHY DEX LP";
    string public constant symbol = "ZLP";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    // ---- pool ----
    uint256 public constant MINIMUM_LIQUIDITY = 1000;
    address public immutable factory;
    address public immutable token0;
    address public immutable token1;

    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;

    uint256 public price0CumulativeLast;
    uint256 public price1CumulativeLast;
    /// reserve0 * reserve1 after the last liquidity event (only kept while the protocol fee is on).
    uint256 public kLast;

    uint256 private unlocked = 1;

    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(address indexed sender, uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out, address indexed to);
    event Sync(uint112 reserve0, uint112 reserve1);

    error Locked();
    error Overflow();
    error TransferFailed();
    error InsufficientLiquidityMinted();
    error InsufficientLiquidityBurned();
    error InsufficientOutputAmount();
    error InsufficientInputAmount();
    error InsufficientLiquidity();
    error InvalidTo();
    error K();
    error InsufficientAllowance();
    error InsufficientBalance();

    modifier lock() {
        if (unlocked != 1) revert Locked();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    /// Created by the factory with CREATE2; the tokens come from the factory,
    /// so the init code (and so every pair's address) does not depend on them.
    constructor() {
        factory = msg.sender;
        (token0, token1) = IZetaphyFactoryForPair(msg.sender).pairParameters();
    }

    function getReserves() public view returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    // ---- ERC-20 ----

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - value; }
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        uint256 b = balanceOf[from];
        if (b < value) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = b - value;
            balanceOf[to] += value; // cannot overflow: sum of balances == totalSupply
        }
        emit Transfer(from, to, value);
    }

    function _mint(address to, uint256 value) private {
        totalSupply += value;
        unchecked { balanceOf[to] += value; }
        emit Transfer(address(0), to, value);
    }

    function _burn(address from, uint256 value) private {
        balanceOf[from] -= value;
        unchecked { totalSupply -= value; }
        emit Transfer(from, address(0), value);
    }

    // ---- pool internals ----

    /// transfer(), accepting tokens that return nothing (USDT-style) but not ones that return false.
    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _balance(address token) private view returns (uint256) {
        return IERC20Balance(token).balanceOf(address(this));
    }

    /// New reserves; on the block's first touch, the price accumulators grow by
    /// the price before this update times the seconds since the last one.
    function _update(uint256 balance0, uint256 balance1, uint112 _reserve0, uint112 _reserve1) private {
        if (balance0 > type(uint112).max || balance1 > type(uint112).max) revert Overflow();
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        unchecked {
            uint32 timeElapsed = blockTimestamp - blockTimestampLast; // wraps around, by design
            if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
                // UQ112.112: (reserve1 << 112) / reserve0 fits in 224 bits; the products wrap, by design.
                price0CumulativeLast += ((uint256(_reserve1) << 112) / _reserve0) * timeElapsed;
                price1CumulativeLast += ((uint256(_reserve0) << 112) / _reserve1) * timeElapsed;
            }
        }
        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = blockTimestamp;
        emit Sync(reserve0, reserve1);
    }

    /// Protocol fee: 1/6 of the growth of sqrt(k) since the last liquidity event, as LP tokens to feeTo.
    function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns (bool feeOn) {
        address feeTo = IZetaphyFactoryForPair(factory).feeTo();
        feeOn = feeTo != address(0);
        uint256 _kLast = kLast;
        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = _sqrt(uint256(_reserve0) * _reserve1);
                uint256 rootKLast = _sqrt(_kLast);
                if (rootK > rootKLast) {
                    uint256 liquidity = (totalSupply * (rootK - rootKLast)) / (rootK * 5 + rootKLast);
                    if (liquidity > 0) _mint(feeTo, liquidity);
                }
            }
        } else if (_kLast != 0) {
            kLast = 0;
        }
    }

    // ---- pool: called by the router (or anyone who transferred tokens in first) ----

    /// LP tokens for the tokens sent to the pair since the last update.
    function mint(address to) external lock returns (uint256 liquidity) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        uint256 balance0 = _balance(token0);
        uint256 balance1 = _balance(token1);
        uint256 amount0 = balance0 - _reserve0;
        uint256 amount1 = balance1 - _reserve1;

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply; // after _mintFee, which may change it
        if (_totalSupply == 0) {
            uint256 root = _sqrt(amount0 * amount1);
            if (root <= MINIMUM_LIQUIDITY) revert InsufficientLiquidityMinted();
            liquidity = root - MINIMUM_LIQUIDITY;
            _mint(address(0), MINIMUM_LIQUIDITY); // locked forever
        } else {
            uint256 l0 = (amount0 * _totalSupply) / _reserve0;
            uint256 l1 = (amount1 * _totalSupply) / _reserve1;
            liquidity = l0 < l1 ? l0 : l1;
        }
        if (liquidity == 0) revert InsufficientLiquidityMinted();
        _mint(to, liquidity);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Mint(msg.sender, amount0, amount1);
    }

    /// Burns the LP tokens sent to the pair; their share of both tokens goes to `to`.
    function burn(address to) external lock returns (uint256 amount0, uint256 amount1) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        address _token0 = token0;
        address _token1 = token1;
        uint256 balance0 = _balance(_token0);
        uint256 balance1 = _balance(_token1);
        uint256 liquidity = balanceOf[address(this)];

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply;
        amount0 = (liquidity * balance0) / _totalSupply; // pro rata of balances, not reserves
        amount1 = (liquidity * balance1) / _totalSupply;
        if (amount0 == 0 || amount1 == 0) revert InsufficientLiquidityBurned();
        _burn(address(this), liquidity);
        _safeTransfer(_token0, to, amount0);
        _safeTransfer(_token1, to, amount1);
        balance0 = _balance(_token0);
        balance1 = _balance(_token1);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Burn(msg.sender, amount0, amount1, to);
    }

    /// Sends the outputs to `to` (then calls it back if `data` is not empty);
    /// the inputs must be in the pair by the end, such that the balances less
    /// 0.3% of the inputs keep k at least where it was.
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external lock {
        if (amount0Out == 0 && amount1Out == 0) revert InsufficientOutputAmount();
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        if (amount0Out >= _reserve0 || amount1Out >= _reserve1) revert InsufficientLiquidity();

        uint256 balance0;
        uint256 balance1;
        {
            address _token0 = token0;
            address _token1 = token1;
            if (to == _token0 || to == _token1) revert InvalidTo();
            if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); // optimistic
            if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out);
            if (data.length > 0) IZetaphyDexCallee(to).zetaphyDexCall(msg.sender, amount0Out, amount1Out, data);
            balance0 = _balance(_token0);
            balance1 = _balance(_token1);
        }
        uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        if (amount0In == 0 && amount1In == 0) revert InsufficientInputAmount();
        {
            uint256 balance0Adjusted = balance0 * 1000 - amount0In * 3;
            uint256 balance1Adjusted = balance1 * 1000 - amount1In * 3;
            if (balance0Adjusted * balance1Adjusted < uint256(_reserve0) * _reserve1 * 1_000_000) revert K();
        }

        _update(balance0, balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    /// Sends whatever is above the reserves (e.g. tokens sent by mistake) to `to`.
    function skim(address to) external lock {
        address _token0 = token0;
        address _token1 = token1;
        _safeTransfer(_token0, to, _balance(_token0) - reserve0);
        _safeTransfer(_token1, to, _balance(_token1) - reserve1);
    }

    /// Sets the reserves to the balances (e.g. after a token's balance changed on its own).
    function sync() external lock {
        _update(_balance(token0), _balance(token1), reserve0, reserve1);
    }

    function _sqrt(uint256 y) private pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/ZetaphyRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY DEX router (MIT, written from scratch). The functions keep the
// Uniswap V2 router's names and argument order, so wallets that decode V2
// calls show them; "ETH" in a name means the chain's native coin (ZETAPHY,
// ticker ZTPHY), which the router wraps through WETH():
//   - on ZETAPHY: the native ERC-20 precompile 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE
//     (Cosmos EVM's WERC20: its balanceOf is the native balance, transfer moves
//     native coins, deposit() gives the coins straight back, withdraw() is a no-op);
//   - elsewhere (and in the unit tests): the WZETAPHY contract, a classic WETH.
// The router works with both, because it only relies on deposit, withdraw,
// transfer and balanceOf.
//
// Every function checks a deadline; every swap and liquidity call takes a
// minimum (or maximum) amount, so the caller sets the slippage it accepts.
// The *SupportingFeeOnTransferTokens functions work with tokens that take a
// cut on transfer: they measure what each pair actually received.
//
// Neuro: when governance set factory.threatRegistry() (zero = off), the
// router refuses to swap INTO, or add liquidity with, a token whose flag is
// enforced in Neuro's ThreatRegistry (isContractEnforced: the token's address
// on this chain, or its exact code). Selling such a token and removing
// liquidity always work, so nobody is locked in. A flag is automated,
// reproducible code analysis, not an accusation (docs/LEGAL.md).
//
// Governance's reach over the router (stated plainly, see README):
//   - the registry check FAILS CLOSED: if the registry governance set stops
//     answering (reverts, returns junk, or needs more than REGISTRY_GAS), or
//     answers "enforced" for everything, every swap into a token other than
//     the native coin, and every add of liquidity, is refused router-wide.
//     Selling into the native coin and removing liquidity never ask the
//     registry, so they keep working; the pairs themselves never ask it either.
//     Governance lifts such a stop by setting the registry to zero.
//   - sweep(to): native coins that reached the router outside a call (a
//     precompile transfer, a self-destruct) can be sent on by governance. The
//     router holds no user funds between calls, so nothing of a user's is reachable.
//
// First deposit: while a pair's totalSupply is 0 (nobody has minted LP yet),
// addLiquidity takes the desired amounts as given, even if someone donated
// tokens and called sync() so that the reserves are not zero. The donation
// then belongs to the first LP, and the first LP's price is not set by
// whoever made the donation (security finding M3).

interface IFactory {
    function getPair(address, address) external view returns (address);
    function createPair(address, address) external returns (address);
    function threatRegistry() external view returns (address);
    function governance() external view returns (address);
    function PAIR_CODE_HASH() external view returns (bytes32);
}

interface IPair {
    function getReserves() external view returns (uint112, uint112, uint32);
    function totalSupply() external view returns (uint256);
    function mint(address to) external returns (uint256);
    function burn(address to) external returns (uint256, uint256);
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external;
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IWNative {
    function deposit() external payable;
    function withdraw(uint256) external;
}

interface IERC20Min {
    function balanceOf(address) external view returns (uint256);
}

interface IThreatView {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

contract ZetaphyRouter {
    address public immutable factory;
    address public immutable WETH;
    bytes32 private immutable pairCodeHash;

    /// Gas given to each ThreatRegistry query: a registry that needs more fails closed (RegistryUnavailable).
    uint256 public constant REGISTRY_GAS = 100_000;

    error Expired();
    error InvalidPath();
    error InsufficientAAmount();
    error InsufficientBAmount();
    error InsufficientAmount();
    error InsufficientLiquidity();
    error InsufficientInputAmount();
    error InsufficientOutputAmount();
    error ExcessiveInputAmount();
    error IdenticalAddresses();
    error ZeroAddress();
    error TransferFailed();
    error NativeTransferFailed();
    error OnlyWNative();
    error NotGovernance();
    /// Neuro's ThreatRegistry has an enforced flag on this token (reason: ThreatRegistry.Reason).
    error TokenEnforced(address token, uint8 reason);
    /// The ThreatRegistry governance set did not answer (within REGISTRY_GAS); fails closed.
    error RegistryUnavailable();

    event Swept(address indexed to, uint256 amount);

    modifier ensure(uint256 deadline) {
        if (deadline < block.timestamp) revert Expired();
        _;
    }

    constructor(address factory_, address wnative) {
        if (factory_ == address(0) || wnative == address(0)) revert ZeroAddress();
        factory = factory_;
        WETH = wnative;
        pairCodeHash = IFactory(factory_).PAIR_CODE_HASH();
    }

    /// Native coins only come from WZETAPHY.withdraw (the precompile moves them without a call).
    receive() external payable {
        if (msg.sender != WETH) revert OnlyWNative();
    }

    /// Governance only: sends the router's whole native balance to `to`. Coins
    /// can only be there by mistake (a precompile transfer or a self-destruct
    /// skips receive()); the router holds no user funds between calls.
    function sweep(address to) external {
        if (msg.sender != IFactory(factory).governance()) revert NotGovernance();
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = address(this).balance;
        _sendNative(to, amount);
        emit Swept(to, amount);
    }

    // ---- Neuro ----

    /// Reverts with TokenEnforced if the registry (when set) has an enforced flag on `token`.
    function _refuseEnforced(address registry, address token) private view {
        if (token == WETH) return;
        (bool ok, bytes memory r) = registry.staticcall{gas: REGISTRY_GAS}(abi.encodeCall(IThreatView.isContractEnforced, (token)));
        if (!ok || r.length < 64) revert RegistryUnavailable();
        (bool enforced, uint8 reason) = abi.decode(r, (bool, uint8));
        if (enforced) revert TokenEnforced(token, reason);
    }

    /// Every token a swap along `path` receives into a pool or hands out (path[1..]); not the one sold.
    function _checkPath(address[] calldata path) private view {
        address registry = IFactory(factory).threatRegistry();
        if (registry == address(0)) return;
        for (uint256 i = 1; i < path.length; i++) _refuseEnforced(registry, path[i]);
    }

    function _checkPair(address a, address b) private view {
        address registry = IFactory(factory).threatRegistry();
        if (registry == address(0)) return;
        _refuseEnforced(registry, a);
        _refuseEnforced(registry, b);
    }

    // ---- library ----

    function sortTokens(address tokenA, address tokenB) public pure returns (address token0, address token1) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert ZeroAddress();
    }

    /// The pair's CREATE2 address (it may not exist yet).
    function pairFor(address tokenA, address tokenB) public view returns (address) {
        (address token0, address token1) = sortTokens(tokenA, tokenB);
        return address(uint160(uint256(keccak256(abi.encodePacked(
            hex"ff", factory, keccak256(abi.encodePacked(token0, token1)), pairCodeHash)))));
    }

    function getReserves(address tokenA, address tokenB) public view returns (uint256 reserveA, uint256 reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint256 r0, uint256 r1,) = IPair(pairFor(tokenA, tokenB)).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (r0, r1) : (r1, r0);
    }

    /// The amount of B worth amountA at the current price (no fee, no price impact).
    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB) public pure returns (uint256) {
        if (amountA == 0) revert InsufficientAmount();
        if (reserveA == 0 || reserveB == 0) revert InsufficientLiquidity();
        return (amountA * reserveB) / reserveA;
    }

    /// Output for an exact input, after the 0.3% fee.
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256) {
        if (amountIn == 0) revert InsufficientInputAmount();
        if (reserveIn == 0 || reserveOut == 0) revert InsufficientLiquidity();
        uint256 amountInWithFee = amountIn * 997;
        return (amountInWithFee * reserveOut) / (reserveIn * 1000 + amountInWithFee);
    }

    /// Input needed for an exact output, after the 0.3% fee (rounded up).
    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256) {
        if (amountOut == 0) revert InsufficientOutputAmount();
        if (reserveIn == 0 || reserveOut == 0 || amountOut >= reserveOut) revert InsufficientLiquidity();
        return (reserveIn * amountOut * 1000) / ((reserveOut - amountOut) * 997) + 1;
    }

    function getAmountsOut(uint256 amountIn, address[] calldata path) public view returns (uint256[] memory amounts) {
        if (path.length < 2) revert InvalidPath();
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        for (uint256 i; i < path.length - 1; i++) {
            (uint256 rIn, uint256 rOut) = getReserves(path[i], path[i + 1]);
            amounts[i + 1] = getAmountOut(amounts[i], rIn, rOut);
        }
    }

    function getAmountsIn(uint256 amountOut, address[] calldata path) public view returns (uint256[] memory amounts) {
        if (path.length < 2) revert InvalidPath();
        amounts = new uint256[](path.length);
        amounts[amounts.length - 1] = amountOut;
        for (uint256 i = path.length - 1; i > 0; i--) {
            (uint256 rIn, uint256 rOut) = getReserves(path[i - 1], path[i]);
            amounts[i - 1] = getAmountIn(amounts[i], rIn, rOut);
        }
    }

    // ---- token transfers ----

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _sendNative(address to, uint256 value) private {
        (bool ok,) = to.call{value: value}("");
        if (!ok) revert NativeTransferFailed();
    }

    /// Wraps `amount` of the native coin and sends it to `pair`.
    function _wrapTo(address pair, uint256 amount) private {
        IWNative(WETH).deposit{value: amount}();
        _safeTransfer(WETH, pair, amount);
    }

    // ---- add liquidity ----

    function _addLiquidity(address tokenA, address tokenB, uint256 amountADesired, uint256 amountBDesired, uint256 amountAMin, uint256 amountBMin)
        private returns (uint256 amountA, uint256 amountB)
    {
        _checkPair(tokenA, tokenB);
        address pair = IFactory(factory).getPair(tokenA, tokenB);
        if (pair == address(0)) pair = IFactory(factory).createPair(tokenA, tokenB);
        (uint256 reserveA, uint256 reserveB) = getReserves(tokenA, tokenB);
        // No LP minted yet: a new pool, whatever the reserves (a donation + sync
        // must not set the first LP's price). The first LP sets it and gets the donation.
        if (IPair(pair).totalSupply() == 0 || (reserveA == 0 && reserveB == 0)) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                if (amountBOptimal < amountBMin) revert InsufficientBAmount();
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = quote(amountBDesired, reserveB, reserveA);
                // amountAOptimal <= amountADesired here
                if (amountAOptimal < amountAMin) revert InsufficientAAmount();
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function addLiquidity(
        address tokenA, address tokenB, uint256 amountADesired, uint256 amountBDesired,
        uint256 amountAMin, uint256 amountBMin, address to, uint256 deadline
    ) external ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = pairFor(tokenA, tokenB);
        _safeTransferFrom(tokenA, msg.sender, pair, amountA);
        _safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = IPair(pair).mint(to);
    }

    /// msg.value is the most native coin to add; the rest is refunded.
    function addLiquidityETH(
        address token, uint256 amountTokenDesired, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) external payable ensure(deadline) returns (uint256 amountToken, uint256 amountETH, uint256 liquidity) {
        (amountToken, amountETH) = _addLiquidity(token, WETH, amountTokenDesired, msg.value, amountTokenMin, amountETHMin);
        address pair = pairFor(token, WETH);
        _safeTransferFrom(token, msg.sender, pair, amountToken);
        _wrapTo(pair, amountETH);
        liquidity = IPair(pair).mint(to);
        if (msg.value > amountETH) _sendNative(msg.sender, msg.value - amountETH);
    }

    // ---- remove liquidity ----

    function removeLiquidity(
        address tokenA, address tokenB, uint256 liquidity, uint256 amountAMin, uint256 amountBMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pair = pairFor(tokenA, tokenB);
        if (!IPair(pair).transferFrom(msg.sender, pair, liquidity)) revert TransferFailed();
        (uint256 amount0, uint256 amount1) = IPair(pair).burn(to);
        (address token0,) = sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        if (amountA < amountAMin) revert InsufficientAAmount();
        if (amountB < amountBMin) revert InsufficientBAmount();
    }

    function removeLiquidityETH(
        address token, uint256 liquidity, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(token, WETH, liquidity, amountTokenMin, amountETHMin, address(this), deadline);
        _safeTransfer(token, to, amountToken);
        IWNative(WETH).withdraw(amountETH);
        _sendNative(to, amountETH);
    }

    /// For tokens that take a cut on transfer: passes on whatever token amount the router received.
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token, uint256 liquidity, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountETH) {
        (, amountETH) = removeLiquidity(token, WETH, liquidity, amountTokenMin, amountETHMin, address(this), deadline);
        _safeTransfer(token, to, IERC20Min(token).balanceOf(address(this)));
        IWNative(WETH).withdraw(amountETH);
        _sendNative(to, amountETH);
    }

    // ---- swaps (exact amounts known up front) ----

    /// amounts[0] must already be in the first pair.
    function _swap(uint256[] memory amounts, address[] calldata path, address _to) private {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < path.length - 2 ? pairFor(output, path[i + 2]) : _to;
            IPair(pairFor(input, output)).swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        _checkPath(path);
        amounts = getAmountsOut(amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactTokens(uint256 amountOut, uint256 amountInMax, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > amountInMax) revert ExcessiveInputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapExactETHForTokens(uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsOut(msg.value, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _wrapTo(pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactETH(uint256 amountOut, uint256 amountInMax, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > amountInMax) revert ExcessiveInputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWNative(WETH).withdraw(amounts[amounts.length - 1]);
        _sendNative(to, amounts[amounts.length - 1]);
    }

    function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsOut(amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWNative(WETH).withdraw(amounts[amounts.length - 1]);
        _sendNative(to, amounts[amounts.length - 1]);
    }

    /// msg.value is the most native coin to spend; the rest is refunded.
    function swapETHForExactTokens(uint256 amountOut, address[] calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > msg.value) revert ExcessiveInputAmount();
        _wrapTo(pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
        if (msg.value > amounts[0]) _sendNative(msg.sender, msg.value - amounts[0]);
    }

    // ---- swaps (fee-on-transfer tokens: amounts measured as they arrive) ----

    function _swapSupportingFeeOnTransferTokens(address[] calldata path, address _to) private {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = sortTokens(input, output);
            IPair pair = IPair(pairFor(input, output));
            uint256 amountOutput;
            {
                (uint256 r0, uint256 r1,) = pair.getReserves();
                (uint256 reserveIn, uint256 reserveOut) = input == token0 ? (r0, r1) : (r1, r0);
                uint256 amountInput = IERC20Min(input).balanceOf(address(pair)) - reserveIn;
                amountOutput = getAmountOut(amountInput, reserveIn, reserveOut);
            }
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOutput) : (amountOutput, uint256(0));
            address to = i < path.length - 2 ? pairFor(output, path[i + 2]) : _to;
            pair.swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) {
        if (path.length < 2) revert InvalidPath();
        _checkPath(path);
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amountIn);
        address last = path[path.length - 1];
        uint256 before = IERC20Min(last).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        if (IERC20Min(last).balanceOf(to) - before < amountOutMin) revert InsufficientOutputAmount();
    }

    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external payable ensure(deadline) {
        if (path.length < 2 || path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        _wrapTo(pairFor(path[0], path[1]), msg.value);
        address last = path[path.length - 1];
        uint256 before = IERC20Min(last).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        if (IERC20Min(last).balanceOf(to) - before < amountOutMin) revert InsufficientOutputAmount();
    }

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) {
        if (path.length < 2 || path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amountIn);
        // With the precompile, WETH.balanceOf(router) is the router's native
        // balance, which may hold coins of its own: measure the difference.
        uint256 before = IERC20Min(WETH).balanceOf(address(this));
        _swapSupportingFeeOnTransferTokens(path, address(this));
        uint256 amountOut = IERC20Min(WETH).balanceOf(address(this)) - before;
        if (amountOut < amountOutMin) revert InsufficientOutputAmount();
        IWNative(WETH).withdraw(amountOut);
        _sendNative(to, amountOut);
    }
}

contracts/dlmm/DlmmMath.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ============================================================================
// UNAUDITED. ZETAPHY DLMM (discrete liquidity bins), testnet only.
// ============================================================================
//
// Fixed-point math for the DLMM pair. Ported from our own Solana design
// (programs/swd_amm/src/dlmm.rs, Q64.64 there) to 128.128 on the EVM:
//
//   - A price is a 128.128 fixed-point number (`priceX128` = price * 2^128):
//     raw units of tokenY per raw unit of tokenX (no decimals involved).
//   - price(id) = (1 + binStep / 10_000) ^ id.  Like dlmm.rs, it is computed
//     from the single step DOWN, 10_000 / (10_000 + binStep), raised to |id|
//     by squaring. That base is < 1, so every product of two 128.128 values
//     stays < 2^256 and needs no 512-bit math; a positive id takes the
//     reciprocal at the end (2^256 / result, one division).
//   - Prices are limited to [2^-96, 2^96] (MIN_PRICE_X128 .. MAX_PRICE_X128):
//     outside it the price has too few significant bits (or a bin could hold
//     almost nothing), so such a bin id is refused (PriceOutOfRange). This is
//     what bounds the bin id range for every bin step.
//   - mulDiv / mulDivUp: floor / ceil of a * b / d with a 512-bit product.
//
// Rounding: every function says which way it rounds; the pair always picks
// the direction that favours the pool (inputs and fees up, outputs down).
//
// Written from scratch for ZETAPHY (MIT). The 128.128 price idea is common to
// bin-based AMMs (Trader Joe's Liquidity Book uses it too; its repository
// traderjoe-xyz/joe-v2 is MIT-licensed, checked 2026-10-21), but no code was
// copied from it or from any other project.

library DlmmMath {
    uint256 internal constant SCALE = 128;
    uint256 internal constant ONE_X128 = 1 << 128;
    /// 2^-96 and 2^96 as 128.128 numbers.
    uint256 internal constant MIN_PRICE_X128 = 1 << 32;
    uint256 internal constant MAX_PRICE_X128 = 1 << 224;
    uint256 internal constant BPS = 10_000;
    /// Largest bin step (10% per bin), same ceiling as dlmm.rs (MAX_BIN_STEP_BPS).
    uint256 internal constant MAX_BIN_STEP = 1_000;
    /// Bin ids are int24; the price range above is reached far inside it.
    int256 internal constant MAX_ABS_ID = (1 << 23) - 1;

    error PriceOutOfRange(int256 id);
    error InvalidBinStep();
    error MulDivOverflow();

    /// price(id) as 128.128. Reverts outside [MIN_PRICE_X128, MAX_PRICE_X128].
    /// Negative ids round down (a product of floors), positive ids round up
    /// (the reciprocal of that). A pure function of (id, binStep): every bin
    /// always has the same price, whichever path reached it.
    function getPriceX128(int256 id, uint256 binStep) internal pure returns (uint256 priceX128) {
        if (binStep == 0 || binStep > MAX_BIN_STEP) revert InvalidBinStep();
        if (id > MAX_ABS_ID || id < -MAX_ABS_ID) revert PriceOutOfRange(id);
        if (id == 0) return ONE_X128;
        uint256 n = id < 0 ? uint256(-id) : uint256(id);
        uint256 base = (ONE_X128 * BPS) / (BPS + binStep); // < 2^128
        uint256 r = ONE_X128;
        unchecked {
            // r <= 2^128 and base < 2^128: both products stay below 2^256.
            while (true) {
                if (n & 1 != 0) r = (r * base) >> SCALE;
                n >>= 1;
                if (n == 0) break;
                base = (base * base) >> SCALE;
                if (r < MIN_PRICE_X128) break; // already out of range, stop early
            }
        }
        if (id < 0) {
            if (r < MIN_PRICE_X128) revert PriceOutOfRange(id);
            return r;
        }
        if (r == 0) revert PriceOutOfRange(id);
        priceX128 = type(uint256).max / r; // ~ 2^256 / r, rounds the price up
        if (priceX128 > MAX_PRICE_X128) revert PriceOutOfRange(id);
    }

    /// floor(amount * priceX128 / 2^128): tokenX -> tokenY at a bin's price.
    /// amount < 2^128 and price <= 2^224, so the result is < 2^224.
    function mulPriceDown(uint256 amount, uint256 priceX128) internal pure returns (uint256) {
        uint256 hi = priceX128 >> SCALE;
        uint256 lo = priceX128 & type(uint128).max;
        return amount * hi + ((amount * lo) >> SCALE);
    }

    /// ceil(amount * priceX128 / 2^128).
    function mulPriceUp(uint256 amount, uint256 priceX128) internal pure returns (uint256 r) {
        uint256 hi = priceX128 >> SCALE;
        uint256 lo = priceX128 & type(uint128).max;
        uint256 p = amount * lo;
        r = amount * hi + (p >> SCALE);
        if (p & type(uint128).max != 0) r += 1;
    }

    /// floor(amount * 2^128 / priceX128): tokenY -> tokenX at a bin's price.
    function divPriceDown(uint256 amount, uint256 priceX128) internal pure returns (uint256) {
        return (amount << SCALE) / priceX128;
    }

    /// ceil(amount * 2^128 / priceX128).
    function divPriceUp(uint256 amount, uint256 priceX128) internal pure returns (uint256 r) {
        uint256 n = amount << SCALE;
        r = n / priceX128;
        if (n % priceX128 != 0) r += 1;
    }

    /// floor(a * b / d) with a full 512-bit product; reverts if d == 0 or the result overflows.
    function mulDiv(uint256 a, uint256 b, uint256 d) internal pure returns (uint256 result) {
        unchecked {
            // 512-bit product [p1 p0] = a * b.
            uint256 p0 = a * b;
            uint256 mm = mulmod(a, b, type(uint256).max);
            uint256 p1 = mm - p0 - (mm < p0 ? 1 : 0);
            if (p1 == 0) {
                if (d == 0) revert MulDivOverflow();
                return p0 / d;
            }
            if (d <= p1) revert MulDivOverflow();
            // Subtract the remainder so the division is exact.
            uint256 rem = mulmod(a, b, d);
            p1 -= rem > p0 ? 1 : 0;
            p0 -= rem;
            // Divide out the largest power of two that divides d.
            uint256 twos = d & (~d + 1);
            d /= twos;
            p0 /= twos;
            // 2^256 / twos, and fold the high word into p0.
            p0 |= p1 * ((0 - twos) / twos + 1);
            // d is odd now: its inverse mod 2^256 by Newton's iteration
            // (each step doubles the correct bits: 4 -> 8 -> ... -> 256).
            uint256 inv = (3 * d) ^ 2;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            inv *= 2 - d * inv;
            result = p0 * inv;
        }
    }

    /// ceil(a * b / d).
    function mulDivUp(uint256 a, uint256 b, uint256 d) internal pure returns (uint256 result) {
        result = mulDiv(a, b, d);
        if (mulmod(a, b, d) != 0) {
            if (result == type(uint256).max) revert MulDivOverflow();
            result += 1;
        }
    }

    /// ceil(a * b / d) for small operands (no overflow possible in the callers).
    function ceilDiv(uint256 n, uint256 d) internal pure returns (uint256) {
        return n / d + (n % d == 0 ? 0 : 1);
    }

    /// Index of the most significant set bit (x > 0).
    function msb(uint256 x) internal pure returns (uint256 r) {
        if (x >= 1 << 128) { x >>= 128; r += 128; }
        if (x >= 1 << 64) { x >>= 64; r += 64; }
        if (x >= 1 << 32) { x >>= 32; r += 32; }
        if (x >= 1 << 16) { x >>= 16; r += 16; }
        if (x >= 1 << 8) { x >>= 8; r += 8; }
        if (x >= 1 << 4) { x >>= 4; r += 4; }
        if (x >= 1 << 2) { x >>= 2; r += 2; }
        if (x >= 1 << 1) r += 1;
    }

    /// Index of the least significant set bit (x > 0).
    function lsb(uint256 x) internal pure returns (uint256) {
        unchecked {
            return msb(x & (~x + 1));
        }
    }
}

/// A set of bin indexes (0 .. 2^24-1) as a three-level bitmap, so the swap can
/// jump straight to the next bin that holds liquidity instead of stepping
/// through empty bins one by one (dlmm.rs stepped bin by bin inside a fixed
/// 201-bin array; the EVM version has no fixed array). Each lookup reads at
/// most 3 + 2 storage words.
library DlmmBinTree {
    uint256 internal constant NONE = type(uint256).max;

    struct Tree {
        uint256 level2; // bit k: level1[k] != 0
        mapping(uint256 => uint256) level1; // bit j of level1[k]: level0[k*256+j] != 0
        mapping(uint256 => uint256) level0; // bit b of level0[w]: index w*256+b is in the set
    }

    function contains(Tree storage t, uint256 i) internal view returns (bool) {
        return t.level0[i >> 8] & (1 << (i & 255)) != 0;
    }

    function add(Tree storage t, uint256 i) internal {
        uint256 k0 = i >> 8;
        uint256 w0 = t.level0[k0];
        uint256 b0 = 1 << (i & 255);
        if (w0 & b0 != 0) return;
        t.level0[k0] = w0 | b0;
        if (w0 != 0) return;
        uint256 k1 = i >> 16;
        uint256 w1 = t.level1[k1];
        t.level1[k1] = w1 | (1 << (k0 & 255));
        if (w1 != 0) return;
        t.level2 |= 1 << k1;
    }

    function remove(Tree storage t, uint256 i) internal {
        uint256 k0 = i >> 8;
        uint256 w0 = t.level0[k0];
        uint256 b0 = 1 << (i & 255);
        if (w0 & b0 == 0) return;
        w0 &= ~b0;
        t.level0[k0] = w0;
        if (w0 != 0) return;
        uint256 k1 = i >> 16;
        uint256 w1 = t.level1[k1] & ~(1 << (k0 & 255));
        t.level1[k1] = w1;
        if (w1 != 0) return;
        t.level2 &= ~(1 << k1);
    }

    /// The largest index in the set that is < i, or NONE.
    function below(Tree storage t, uint256 i) internal view returns (uint256) {
        uint256 k0 = i >> 8;
        uint256 w = t.level0[k0] & ((1 << (i & 255)) - 1);
        if (w != 0) return (k0 << 8) | DlmmMath.msb(w);
        uint256 k1 = i >> 16;
        w = t.level1[k1] & ((1 << (k0 & 255)) - 1);
        if (w == 0) {
            w = t.level2 & ((1 << k1) - 1);
            if (w == 0) return NONE;
            k1 = DlmmMath.msb(w);
            w = t.level1[k1];
        }
        k0 = (k1 << 8) | DlmmMath.msb(w);
        return (k0 << 8) | DlmmMath.msb(t.level0[k0]);
    }

    /// The smallest index in the set that is > i, or NONE.
    function above(Tree storage t, uint256 i) internal view returns (uint256) {
        uint256 k0 = i >> 8;
        uint256 w;
        unchecked {
            w = t.level0[k0] & ~((2 << (i & 255)) - 1); // 2 << 255 wraps to 0: mask 0
        }
        if (w != 0) return (k0 << 8) | DlmmMath.lsb(w);
        uint256 k1 = i >> 16;
        unchecked {
            w = t.level1[k1] & ~((2 << (k0 & 255)) - 1);
        }
        if (w == 0) {
            unchecked {
                w = t.level2 & ~((2 << k1) - 1);
            }
            if (w == 0) return NONE;
            k1 = DlmmMath.lsb(w);
            w = t.level1[k1];
        }
        k0 = (k1 << 8) | DlmmMath.lsb(w);
        return (k0 << 8) | DlmmMath.lsb(t.level0[k0]);
    }
}

contracts/dlmm/ZetaphyDlmmFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ============================================================================
// UNAUDITED. ZETAPHY DLMM factory, testnet only.
// ============================================================================

import {ZetaphyDlmmPair, ZetaphyDlmmPairDeployer, DlmmPairParameters} from "./ZetaphyDlmmPair.sol";
import {DlmmMath} from "./DlmmMath.sol";

/// Same view of Neuro's ThreatRegistry as ZetaphyFactory uses.
interface IThreatRegistryViewDlmm {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

/// @title ZetaphyDlmmFactory: one ZetaphyDlmmPair per (token pair, bin step), CREATE2.
/// @notice UNAUDITED. Anyone may create a pair for a bin step governance has
///         enabled (a "preset": the bin step's base fee and volatility-fee
///         parameters, copied into the pair at creation and fixed for its life).
///
///         All admin functions sit behind ONE role, `governance` (onlyGov), so
///         the whole role can be handed to a TimelockController (or a multisig)
///         in two steps: setGovernance(timelock), then the timelock executes
///         acceptGovernance(). Governance may:
///           - setPreset / removePreset: the bin steps and fees of FUTURE pairs;
///           - setFeeTo: where protocol fees go (collectProtocolFees on a pair);
///           - setDefaultProtocolShare / setPairProtocolShare: the protocol's
///             part of the swap fee (0 by default, at most 50% of the fee);
///           - setThreatRegistry: Neuro's ThreatRegistry for the DLMM router
///             (zero = off; the router fails closed while it is set, exactly
///             like ZetaphyFactory / ZetaphyRouter);
///           - sweep the DLMM router's stray native coins.
///         Governance cannot move anyone's funds, pause a pair, change an
///         existing pair's fees or bin step, or upgrade anything (no proxies).
contract ZetaphyDlmmFactory {
    struct Preset {
        uint16 baseFeeBps;
        uint16 maxDynamicFeeBps;
        uint32 variableFeeControl; // 0 = no volatility fee
        uint32 filterPeriod;
        uint32 decayPeriod;
        uint16 reductionFactor;
        uint32 maxVolatilityAccumulator;
        bool enabled;
    }

    /// Bounds on presets (swdmm_math.rs: MAX_DYNAMIC_FEE_BPS = 1_000; validate_dynamic_fee).
    uint256 public constant MAX_BASE_FEE_BPS = 1_000;
    uint256 public constant MAX_DYNAMIC_FEE_BPS = 1_000;
    uint256 public constant MAX_PROTOCOL_SHARE_BPS = 5_000;
    /// Gas for the registry check in setThreatRegistry (same as ZetaphyFactory).
    uint256 public constant REGISTRY_GAS = 100_000;

    address public governance;
    address public pendingGovernance;
    address public feeTo;
    address public threatRegistry;
    uint16 public defaultProtocolShareBps;

    mapping(uint16 => Preset) public presets;
    uint16[] private _presetSteps;
    /// getPair[token0][token1][binStep] (both orders filled).
    mapping(address => mapping(address => mapping(uint16 => address))) public getPair;
    address[] public allPairs;

    /// Deploys the pairs (it holds their init code). pair =
    /// CREATE2(pairDeployer, keccak256(tokenX, tokenY, binStep), PAIR_CODE_HASH).
    address public immutable pairDeployer;
    /// keccak256 of ZetaphyDlmmPair's creation code.
    bytes32 public immutable PAIR_CODE_HASH;

    event PairCreated(address indexed tokenX, address indexed tokenY, uint16 indexed binStep, address pair, int24 activeId, uint256 allPairsLength);
    event PresetSet(uint16 indexed binStep, Preset preset);
    event PresetRemoved(uint16 indexed binStep);
    event FeeToSet(address feeTo);
    event ThreatRegistrySet(address registry);
    event DefaultProtocolShareSet(uint16 shareBps);
    event PairProtocolShareSet(address indexed pair, uint16 shareBps);
    event GovernanceProposed(address governance);
    event GovernanceSet(address governance);

    error IdenticalAddresses();
    error ZeroAddress();
    error PairExists();
    error PresetNotEnabled();
    error InvalidPreset();
    error NotGovernance();
    error NotPendingGovernance();
    error NotARegistry();
    error ShareTooHigh();
    error UnknownPair();

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
        ZetaphyDlmmPairDeployer d = new ZetaphyDlmmPairDeployer();
        pairDeployer = address(d);
        PAIR_CODE_HASH = d.PAIR_CODE_HASH();
        emit GovernanceSet(governance_);
    }

    // ---- views ----

    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    function presetSteps() external view returns (uint16[] memory) {
        return _presetSteps;
    }

    // ---- pairs ----

    /// Creates the pair of tokenA and tokenB for an enabled bin step, with its
    /// active bin (starting price) at `activeId`. tokenX is the lower address.
    function createPair(address tokenA, address tokenB, uint16 binStep, int24 activeId) external returns (address pair) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (address tokenX, address tokenY) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (tokenX == address(0)) revert ZeroAddress();
        if (getPair[tokenX][tokenY][binStep] != address(0)) revert PairExists();
        Preset memory p = presets[binStep];
        if (!p.enabled) revert PresetNotEnabled();
        DlmmMath.getPriceX128(activeId, binStep); // a starting bin without a valid price is refused
        DlmmPairParameters memory params = DlmmPairParameters({
            factory: address(this), tokenX: tokenX, tokenY: tokenY, binStep: binStep, activeId: activeId,
            baseFeeBps: p.baseFeeBps, maxDynamicFeeBps: p.maxDynamicFeeBps, variableFeeControl: p.variableFeeControl,
            filterPeriod: p.filterPeriod, decayPeriod: p.decayPeriod, reductionFactor: p.reductionFactor,
            maxVolatilityAccumulator: p.maxVolatilityAccumulator, protocolShareBps: defaultProtocolShareBps
        });
        pair = ZetaphyDlmmPairDeployer(pairDeployer).deploy(keccak256(abi.encodePacked(tokenX, tokenY, binStep)), params);
        getPair[tokenX][tokenY][binStep] = pair;
        getPair[tokenY][tokenX][binStep] = pair;
        allPairs.push(pair);
        emit PairCreated(tokenX, tokenY, binStep, pair, activeId, allPairs.length);
    }

    // ---- governance ----

    /// Enables (or changes) a bin step for NEW pairs; existing pairs keep theirs.
    function setPreset(uint16 binStep, Preset calldata p) external onlyGov {
        if (binStep == 0 || binStep > DlmmMath.MAX_BIN_STEP) revert InvalidPreset();
        if (p.baseFeeBps > MAX_BASE_FEE_BPS) revert InvalidPreset();
        if (p.variableFeeControl != 0) {
            // swdmm_math.rs validate_dynamic_fee
            if (p.maxDynamicFeeBps == 0 || p.maxDynamicFeeBps > MAX_DYNAMIC_FEE_BPS) revert InvalidPreset();
            if (p.filterPeriod >= p.decayPeriod) revert InvalidPreset();
            if (p.reductionFactor > 10_000) revert InvalidPreset();
            if (p.maxVolatilityAccumulator == 0) revert InvalidPreset();
        }
        if (!presets[binStep].enabled) _presetSteps.push(binStep);
        Preset memory q = p;
        q.enabled = true;
        presets[binStep] = q;
        emit PresetSet(binStep, q);
    }

    /// Stops new pairs with this bin step; existing pairs are not affected.
    function removePreset(uint16 binStep) external onlyGov {
        if (!presets[binStep].enabled) revert PresetNotEnabled();
        delete presets[binStep];
        uint256 n = _presetSteps.length;
        for (uint256 i; i < n; i++) {
            if (_presetSteps[i] == binStep) {
                _presetSteps[i] = _presetSteps[n - 1];
                _presetSteps.pop();
                break;
            }
        }
        emit PresetRemoved(binStep);
    }

    function setFeeTo(address feeTo_) external onlyGov {
        feeTo = feeTo_;
        emit FeeToSet(feeTo_);
    }

    /// The protocol share new pairs start with.
    function setDefaultProtocolShare(uint16 shareBps) external onlyGov {
        if (shareBps > MAX_PROTOCOL_SHARE_BPS) revert ShareTooHigh();
        defaultProtocolShareBps = shareBps;
        emit DefaultProtocolShareSet(shareBps);
    }

    /// The protocol share of an existing pair (made by this factory).
    function setPairProtocolShare(address pair, uint16 shareBps) external onlyGov {
        ZetaphyDlmmPair p = ZetaphyDlmmPair(pair);
        if (getPair[p.tokenX()][p.tokenY()][p.binStep()] != pair) revert UnknownPair();
        p.setProtocolShare(shareBps);
        emit PairProtocolShareSet(pair, shareBps);
    }

    /// Zero switches the router's Neuro check off. A nonzero address must
    /// answer isContractEnforced within REGISTRY_GAS (checked here).
    function setThreatRegistry(address registry) external onlyGov {
        if (registry != address(0)) {
            (bool ok, bytes memory r) = registry.staticcall{gas: REGISTRY_GAS}(abi.encodeCall(IThreatRegistryViewDlmm.isContractEnforced, (address(this))));
            if (!ok || r.length < 64) revert NotARegistry();
        }
        threatRegistry = registry;
        emit ThreatRegistrySet(registry);
    }

    /// Step 1 of handing governance over (e.g. to a TimelockController).
    function setGovernance(address next) external onlyGov {
        pendingGovernance = next;
        emit GovernanceProposed(next);
    }

    /// Step 2: the new governance accepts (a timelock executes this call).
    function acceptGovernance() external {
        if (msg.sender != pendingGovernance) revert NotPendingGovernance();
        governance = msg.sender;
        pendingGovernance = address(0);
        emit GovernanceSet(msg.sender);
    }
}

contracts/dlmm/ZetaphyDlmmPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ============================================================================
// UNAUDITED. ZETAPHY DLMM pair (discrete liquidity bins), testnet only.
// Not reviewed by any third party. Do not put value you cannot lose in it.
// ============================================================================
//
// A port of our own Solana DLMM (programs/swd_amm/src/dlmm.rs, with the
// volatility fee of swdmm_math.rs) to the EVM, written from scratch (MIT):
//
//   - Liquidity sits in BINS. Bin `id` trades at the fixed price
//     (1 + binStep/10_000)^id tokenY per tokenX (DlmmMath.getPriceX128,
//     128.128 fixed point). Inside a bin the price does not move.
//   - The ACTIVE bin is the current price. Bins above it hold only tokenX
//     (sold as the price rises), bins below it only tokenY; the active bin
//     may hold both. Deposits must respect this (SingleSidedViolation).
//   - A swap starts at the active bin and crosses bins in its direction
//     (X in: down, Y in: up), jumping over empty bins with a bitmap
//     (DlmmBinTree). At most MAX_BINS_CROSSED bins per swap (gas bound).
//     A swap that cannot be filled reverts (OutOfLiquidity); nothing is
//     ever partly filled.
//   - Shares are per bin (an internal ERC-1155-like ledger, see below).
//     The first deposit into an empty bin mints its value in tokenY scaled
//     by 2^128: x * price + y * 2^128 (exact, no rounding). Later deposits
//     mint in proportion to the bin's current reserves and only take the
//     amounts in the bin's own X:Y ratio (the rest is refunded): a deposit
//     can never swap at the bin price for free.
//   - Fee = base fee + volatility fee (as in swdmm_math.rs): the volatility
//     accumulator grows with the number of bins the price moved from a
//     reference bin, decays with time, and is capped. The fee of each bin is
//     taken from the input used in that bin and stays in that bin (its LPs),
//     except the protocol share, which governance sets (0 by default) and
//     which is paid to the factory's feeTo.
//   - Internal accounting: reserves are tracked in storage; the token
//     balances are only read to see what came in. Tokens sent to the pair
//     outside a call (donations) never change a bin or the price; the next
//     caller's input includes them, or skim() takes them.
//   - Rounding is always in the pool's favour: inputs and fees round up,
//     outputs and minted shares round down.
//   - No flash swaps and no callbacks into user code. Every state-changing
//     function takes one reentrancy lock; state is written before tokens
//     are sent out (checks-effects-interactions).
//   - Fee-on-transfer and rebasing tokens are not supported: the router
//     refuses inputs that arrive short, and after a swap the pair checks
//     that it still holds what it accounts for (BalanceBelowReserves).
//   - No admin can move funds, pause the pair or change its fees. The
//     factory (governance) can only set the protocol share (capped).

import {DlmmMath, DlmmBinTree} from "./DlmmMath.sol";

/// Parameters a new pair reads from its deployer in its constructor.
struct DlmmPairParameters {
    address factory;
    address tokenX;
    address tokenY;
    uint16 binStep;
    int24 activeId;
    uint16 baseFeeBps;
    uint16 maxDynamicFeeBps;
    uint32 variableFeeControl;
    uint32 filterPeriod;
    uint32 decayPeriod;
    uint16 reductionFactor;
    uint32 maxVolatilityAccumulator;
    uint16 protocolShareBps;
}

interface IDlmmFactoryForPair {
    function feeTo() external view returns (address);
}

interface IDlmmPairDeployer {
    function pairParameters() external view returns (DlmmPairParameters memory);
}

interface IERC20DlmmPair {
    function balanceOf(address) external view returns (uint256);
}

contract ZetaphyDlmmPair {
    using DlmmBinTree for DlmmBinTree.Tree;

    // ---- limits ----
    /// Most bins one swap may cross (counting only bins with liquidity, plus
    /// the active bin). dlmm.rs used 30 on Solana; the EVM's gas allows more.
    uint256 public constant MAX_BINS_CROSSED = 100;
    /// Most bins one mint / burn / transfer may touch.
    uint256 public constant MAX_BINS_PER_CALL = 100;
    /// Ceilings on the fee (base + volatility) and on the protocol's part of it.
    uint256 public constant MAX_TOTAL_FEE_BPS = 1_000;
    uint256 public constant MAX_PROTOCOL_SHARE_BPS = 5_000;
    uint256 private constant BPS = 10_000;
    uint256 private constant ID_OFFSET = 1 << 23;

    // ---- immutable configuration ----
    address public immutable factory;
    address public immutable tokenX;
    address public immutable tokenY;
    uint16 public immutable binStep;
    uint16 public immutable baseFeeBps;
    uint16 public immutable maxDynamicFeeBps;
    uint32 public immutable variableFeeControl;
    uint32 public immutable filterPeriod;
    uint32 public immutable decayPeriod;
    uint16 public immutable reductionFactor;
    uint32 public immutable maxVolatilityAccumulator;

    // ---- state ----
    struct State {
        int24 activeId;
        int24 idReference;
        uint32 volatilityAccumulator;
        uint32 volatilityReference;
        uint40 lastUpdate;
        uint16 protocolShareBps;
    }

    struct Bin {
        uint128 x;
        uint128 y;
    }

    State private _state;
    /// Sums of every bin's reserves (what LPs own).
    uint128 public reserveX;
    uint128 public reserveY;
    /// Protocol fees waiting for collectProtocolFees().
    uint128 public protocolFeesX;
    uint128 public protocolFeesY;
    uint256 private _unlocked = 1;

    mapping(int24 => Bin) private _bins;
    mapping(int24 => uint256) public totalSupply;
    mapping(address => mapping(int24 => uint256)) private _balances;
    mapping(address => mapping(address => bool)) public isApprovedForAll;
    DlmmBinTree.Tree private _tree;

    // ---- events ----
    event Swap(address indexed sender, address indexed to, bool swapForY, uint256 amountIn, uint256 amountOut,
        int24 activeId, uint256 fees, uint256 protocolFees, uint256 volatilityAccumulator);
    event DepositedToBins(address indexed sender, address indexed to, int24[] ids, uint256[] amountsX, uint256[] amountsY, uint256[] shares);
    event WithdrawnFromBins(address indexed sender, address indexed from, address indexed to, int24[] ids, uint256[] shares, uint256 amountX, uint256 amountY);
    event TransferBatch(address indexed operator, address indexed from, address indexed to, int24[] ids, uint256[] amounts);
    event ApprovalForAll(address indexed account, address indexed operator, bool approved);
    event ActiveIdSet(int24 activeId);
    event ProtocolShareSet(uint16 protocolShareBps);
    event ProtocolFeesCollected(address indexed to, uint256 amountX, uint256 amountY);
    event Skimmed(address indexed to, uint256 amountX, uint256 amountY);

    // ---- errors ----
    error Locked();
    error NotFactory();
    error NotApproved();
    error InvalidLength();
    error IdsNotSorted();
    error SingleSidedViolation(int24 id);
    error ZeroShares(int24 id);
    error InsufficientShares(int24 id);
    error InsufficientAmountIn();
    error InsufficientAmountOut();
    error ZeroAmount();
    error OutOfLiquidity();
    error TooManyBinsCrossed();
    error NotEmpty();
    error Overflow();
    error FeeToNotSet();
    error ShareTooHigh();
    error TransferFailed();
    error BalanceBelowReserves();
    error InvalidRecipient();

    modifier lock() {
        if (_unlocked != 1) revert Locked();
        _unlocked = 2;
        _;
        _unlocked = 1;
    }

    /// Created by the factory's ZetaphyDlmmPairDeployer with CREATE2; every
    /// parameter comes from the deployer, so the init code (and the pair's
    /// address) does not depend on them.
    constructor() {
        DlmmPairParameters memory p = IDlmmPairDeployer(msg.sender).pairParameters();
        factory = p.factory;
        tokenX = p.tokenX;
        tokenY = p.tokenY;
        binStep = p.binStep;
        baseFeeBps = p.baseFeeBps;
        maxDynamicFeeBps = p.maxDynamicFeeBps;
        variableFeeControl = p.variableFeeControl;
        filterPeriod = p.filterPeriod;
        decayPeriod = p.decayPeriod;
        reductionFactor = p.reductionFactor;
        maxVolatilityAccumulator = p.maxVolatilityAccumulator;
        DlmmMath.getPriceX128(p.activeId, p.binStep); // the starting bin must have a price
        _state = State({activeId: p.activeId, idReference: p.activeId, volatilityAccumulator: 0, volatilityReference: 0,
            lastUpdate: uint40(block.timestamp), protocolShareBps: p.protocolShareBps});
    }

    // =====================================================================
    // Views
    // =====================================================================

    function getActiveId() external view returns (int24) {
        return _state.activeId;
    }

    function getBin(int24 id) external view returns (uint128 x, uint128 y) {
        Bin memory b = _bins[id];
        return (b.x, b.y);
    }

    function getPriceFromId(int24 id) external view returns (uint256 priceX128) {
        return DlmmMath.getPriceX128(id, binStep);
    }

    function protocolShareBps() external view returns (uint16) {
        return _state.protocolShareBps;
    }

    function getVolatility() external view returns (uint32 volatilityAccumulator, uint32 volatilityReference, int24 idReference, uint40 lastUpdate) {
        State memory s = _state;
        return (s.volatilityAccumulator, s.volatilityReference, s.idReference, s.lastUpdate);
    }

    function balanceOf(address account, int24 id) external view returns (uint256) {
        return _balances[account][id];
    }

    /// The nearest bin with liquidity strictly below (or above) `id`; found = false if none.
    function getNextNonEmptyBin(bool below, int24 id) external view returns (int24 next, bool found) {
        uint256 i = below ? _tree.below(_index(id)) : _tree.above(_index(id));
        if (i == DlmmBinTree.NONE) return (id, false);
        return (_id(i), true);
    }

    /// What swap() would do now with `amountIn`: the output, the input it
    /// could not place (0 unless liquidity runs out), and the total fee.
    function getSwapOut(uint256 amountIn, bool swapForY) external view returns (uint256 amountInLeft, uint256 amountOut, uint256 fees) {
        SwapResult memory r = _runSwap(swapForY, amountIn, false);
        return (r.amountInLeft, r.amountOut, r.fees);
    }

    /// The smallest input for which swap() pays at least `amountOut` now
    /// (amountOutLeft > 0: the pair cannot pay that much). Same bins, prices
    /// and fees as swap(), rounded the same way.
    function getSwapIn(uint256 amountOut, bool swapForY) external view returns (uint256 amountIn, uint256 amountOutLeft, uint256 fees) {
        State memory s = _state;
        _updateReferences(s);
        int24 id = s.activeId;
        amountOutLeft = amountOut;
        uint256 crossed;
        while (amountOutLeft != 0) {
            Bin memory b = _bins[id];
            uint256 binOut = swapForY ? b.y : b.x;
            if (binOut != 0) {
                uint256 feeBps = _feeBps(s, id);
                uint256 price = DlmmMath.getPriceX128(id, binStep);
                uint256 out = amountOutLeft < binOut ? amountOutLeft : binOut;
                uint256 net = swapForY ? DlmmMath.divPriceUp(out, price) : DlmmMath.mulPriceUp(out, price);
                uint256 gross = DlmmMath.ceilDiv(net * BPS, BPS - feeBps);
                amountIn += gross;
                fees += gross - net;
                amountOutLeft -= out;
                if (amountOutLeft == 0) break;
            }
            uint256 i = swapForY ? _tree.below(_index(id)) : _tree.above(_index(id));
            if (i == DlmmBinTree.NONE) break;
            id = _id(i);
            if (++crossed > MAX_BINS_CROSSED) revert TooManyBinsCrossed();
        }
    }

    // =====================================================================
    // Swap
    // =====================================================================

    /// Swaps what was sent to the pair since the last update (tokenX if
    /// swapForY, else tokenY) and sends the output to `to`. Call it in the
    /// same transaction as the transfer in (the router does), with your own
    /// minimum-output check: the pair has none.
    function swap(bool swapForY, address to) external lock returns (uint256 amountOut) {
        if (to == address(0) || to == address(this)) revert InvalidRecipient();
        (address tokenIn, address tokenOut) = swapForY ? (tokenX, tokenY) : (tokenY, tokenX);
        uint256 amountIn = _received(tokenIn, swapForY);
        if (amountIn == 0) revert InsufficientAmountIn();

        SwapResult memory r = _runSwap(swapForY, amountIn, true);
        if (r.amountInLeft != 0) revert OutOfLiquidity();
        amountOut = r.amountOut;
        if (amountOut == 0) revert InsufficientAmountOut();
        for (uint256 k; k < r.touched; k++) {
            uint256 v = r.packed[k];
            _bins[r.ids[k]] = Bin(uint128(v >> 128), uint128(v));
        }
        {
            State memory s = _state;
            s.activeId = r.activeId;
            s.volatilityAccumulator = r.volatilityAccumulator;
            s.lastUpdate = uint40(block.timestamp);
            (s.idReference, s.volatilityReference) = (r.idReference, r.volatilityReference);
            _state = s;
        }

        uint256 toBins = amountIn - r.protocolFees;
        if (swapForY) {
            reserveX = _u128(reserveX + toBins);
            reserveY -= uint128(amountOut);
            protocolFeesX = _u128(protocolFeesX + r.protocolFees);
        } else {
            reserveY = _u128(reserveY + toBins);
            reserveX -= uint128(amountOut);
            protocolFeesY = _u128(protocolFeesY + r.protocolFees);
        }
        _safeTransfer(tokenOut, to, amountOut);
        // A token whose balance can shrink on its own (rebasing) or that took
        // more than it said: refuse to pay out what the pair does not hold.
        _checkSolvent(tokenOut, !swapForY);
        emit Swap(msg.sender, to, swapForY, amountIn, amountOut, r.activeId, r.fees, r.protocolFees, r.volatilityAccumulator);
    }

    struct SwapResult {
        uint256 amountInLeft;
        uint256 amountOut;
        uint256 fees;
        uint256 protocolFees;
        int24 activeId;
        uint32 volatilityAccumulator;
        int24 idReference;
        uint32 volatilityReference;
        // swap() only: the bins the swap changed and their new reserves (x << 128 | y)
        uint256 touched;
        int24[] ids;
        uint256[] packed;
    }

    /// The bin-crossing loop shared by swap() (record = true: also returns
    /// the new reserves of every bin it changed, which swap() then writes)
    /// and getSwapOut() (record = false). A view: one code path for both.
    function _runSwap(bool swapForY, uint256 amountIn, bool record) private view returns (SwapResult memory r) {
        State memory s = _state;
        _updateReferences(s);
        int24 id = s.activeId;
        r.amountInLeft = amountIn;
        if (record) {
            r.ids = new int24[](MAX_BINS_CROSSED + 1);
            r.packed = new uint256[](MAX_BINS_CROSSED + 1);
        }
        uint256 crossed;
        while (true) {
            if (_stepBin(r, s, id, swapForY, record)) break;
            uint256 i = swapForY ? _tree.below(_index(id)) : _tree.above(_index(id));
            if (i == DlmmBinTree.NONE) break; // out of liquidity: the caller decides
            id = _id(i);
            if (++crossed > MAX_BINS_CROSSED) revert TooManyBinsCrossed();
        }
        r.activeId = id;
        r.volatilityAccumulator = s.volatilityAccumulator;
        r.idReference = s.idReference;
        r.volatilityReference = s.volatilityReference;
    }

    /// Trades in bin `id` (if it has output-side liquidity); true when the input is used up.
    function _stepBin(SwapResult memory r, State memory s, int24 id, bool swapForY, bool record) private view returns (bool done) {
        Bin memory b = _bins[id];
        uint256 binOut = swapForY ? b.y : b.x;
        if (binOut == 0) return false;
        uint256 feeBps = _feeBps(s, id);
        (uint256 inUsed, uint256 out, uint256 fee) = _binSwap(binOut, DlmmMath.getPriceX128(id, binStep), feeBps, r.amountInLeft, swapForY);
        uint256 pFee = (fee * s.protocolShareBps) / BPS;
        if (record) {
            if (swapForY) {
                b.x = _u128(b.x + inUsed - pFee);
                b.y -= uint128(out);
            } else {
                b.y = _u128(b.y + inUsed - pFee);
                b.x -= uint128(out);
            }
            r.ids[r.touched] = id;
            r.packed[r.touched] = (uint256(b.x) << 128) | b.y;
            r.touched++;
        }
        r.amountInLeft -= inUsed;
        r.amountOut += out;
        r.fees += fee;
        r.protocolFees += pFee;
        return r.amountInLeft == 0;
    }

    /// One bin: (input used, output, fee). Drains the bin if the input is
    /// enough, else converts all of it. Input and fee round up, output down.
    function _binSwap(uint256 binOut, uint256 price, uint256 feeBps, uint256 amountIn, bool swapForY)
        private pure returns (uint256 inUsed, uint256 out, uint256 fee)
    {
        uint256 netNeeded = swapForY ? DlmmMath.divPriceUp(binOut, price) : DlmmMath.mulPriceUp(binOut, price);
        uint256 grossNeeded = DlmmMath.ceilDiv(netNeeded * BPS, BPS - feeBps);
        if (amountIn >= grossNeeded) return (grossNeeded, binOut, grossNeeded - netNeeded);
        fee = DlmmMath.ceilDiv(amountIn * feeBps, BPS);
        uint256 net = amountIn - fee;
        out = swapForY ? DlmmMath.mulPriceDown(net, price) : DlmmMath.divPriceDown(net, price);
        // net < netNeeded, so out < binOut; kept as a hard stop.
        if (out >= binOut) revert Overflow();
        return (amountIn, out, fee);
    }

    // ---- volatility fee (swdmm_math.rs: update_references / accumulate / variable_fee_bps) ----

    /// At the start of a swap: after filterPeriod without a swap the
    /// reference bin moves to the current one; the volatility carried over
    /// decays by reductionFactor, and to zero after decayPeriod.
    function _updateReferences(State memory s) private view {
        uint256 elapsed = block.timestamp - s.lastUpdate;
        if (elapsed >= filterPeriod) {
            s.idReference = s.activeId;
            s.volatilityReference = elapsed < decayPeriod ? uint32((uint256(s.volatilityAccumulator) * reductionFactor) / BPS) : 0;
        }
    }

    /// Fee (bps) for trading in bin `id`; updates the accumulator: reference
    /// + |id - idReference| * binStep (the price move in bps), capped.
    function _feeBps(State memory s, int24 id) private view returns (uint256 fee) {
        fee = baseFeeBps;
        if (variableFeeControl == 0) return fee;
        int256 d = int256(id) - int256(s.idReference);
        uint256 acc = uint256(s.volatilityReference) + (d < 0 ? uint256(-d) : uint256(d)) * binStep;
        if (acc > maxVolatilityAccumulator) acc = maxVolatilityAccumulator;
        s.volatilityAccumulator = uint32(acc);
        uint256 v = (acc * variableFeeControl) / BPS;
        if (v > maxDynamicFeeBps) v = maxDynamicFeeBps;
        fee += v;
        if (fee > MAX_TOTAL_FEE_BPS) fee = MAX_TOTAL_FEE_BPS;
    }

    // =====================================================================
    // Liquidity
    // =====================================================================

    struct MintCtx {
        int24 active;
        uint256 receivedX;
        uint256 receivedY;
        uint256 usedX;
        uint256 usedY;
    }

    /// Deposits into bins `ids` (strictly increasing) the amounts sent to the
    /// pair since the last update. Bins above the active bin take only X,
    /// bins below only Y. Shares go to `to`; whatever a bin did not take
    /// (and any surplus sent) goes back to `refundTo`.
    function mint(address to, int24[] calldata ids, uint256[] calldata amountsX, uint256[] calldata amountsY, address refundTo)
        external lock returns (uint256 usedX, uint256 usedY, uint256[] memory shares)
    {
        uint256 n = ids.length;
        if (n == 0 || n > MAX_BINS_PER_CALL || amountsX.length != n || amountsY.length != n) revert InvalidLength();
        if (to == address(0)) revert InvalidRecipient();
        MintCtx memory c;
        c.active = _state.activeId;
        c.receivedX = _received(tokenX, true);
        c.receivedY = _received(tokenY, false);
        shares = new uint256[](n);
        for (uint256 i; i < n; i++) {
            if (i > 0 && ids[i] <= ids[i - 1]) revert IdsNotSorted();
            shares[i] = _mintBin(c, to, ids[i], amountsX[i], amountsY[i]);
        }
        (usedX, usedY) = (c.usedX, c.usedY);
        if (usedX == 0 && usedY == 0) revert ZeroAmount();
        if (usedX > c.receivedX || usedY > c.receivedY) revert InsufficientAmountIn();
        reserveX = _u128(reserveX + usedX);
        reserveY = _u128(reserveY + usedY);
        emit TransferBatch(msg.sender, address(0), to, ids, shares);
        emit DepositedToBins(msg.sender, to, ids, amountsX, amountsY, shares);
        if (c.receivedX > usedX) _safeTransfer(tokenX, refundTo, c.receivedX - usedX);
        if (c.receivedY > usedY) _safeTransfer(tokenY, refundTo, c.receivedY - usedY);
    }

    function _mintBin(MintCtx memory c, address to, int24 id, uint256 x, uint256 y) private returns (uint256 minted) {
        if ((id > c.active && y != 0) || (id < c.active && x != 0)) revert SingleSidedViolation(id);
        if (x == 0 && y == 0) return 0;
        uint256 price = DlmmMath.getPriceX128(id, binStep); // refuses bins without a valid price
        Bin memory b = _bins[id];
        uint256 supply = totalSupply[id];
        uint256 takeX;
        uint256 takeY;
        if (supply == 0) {
            // Empty bin: shares = its value in Y, scaled by 2^128 (exact).
            minted = x * price + (y << 128); // reverts on overflow: the bin would be worth > ~2^128 Y
            if (y >= 1 << 128) revert Overflow();
            (takeX, takeY) = (x, y);
            _tree.add(_index(id));
        } else {
            // Non-empty bin: the share of the bin the smaller side buys,
            // rounded down; the amounts it costs, rounded up.
            minted = type(uint256).max;
            if (b.x != 0) minted = DlmmMath.mulDiv(x, supply, b.x);
            if (b.y != 0) {
                uint256 sy = DlmmMath.mulDiv(y, supply, b.y);
                if (sy < minted) minted = sy;
            }
            if (b.x != 0) takeX = DlmmMath.mulDivUp(minted, b.x, supply);
            if (b.y != 0) takeY = DlmmMath.mulDivUp(minted, b.y, supply);
        }
        if (minted == 0) revert ZeroShares(id);
        _bins[id] = Bin(_u128(b.x + takeX), _u128(b.y + takeY));
        totalSupply[id] = supply + minted;
        _balances[to][id] += minted;
        c.usedX += takeX;
        c.usedY += takeY;
    }

    /// Burns `from`'s shares in bins `ids` and sends their part of each bin
    /// (rounded down) to `to`. msg.sender must be `from` or approved by it.
    function burn(address from, address to, int24[] calldata ids, uint256[] calldata shares)
        external lock returns (uint256 amountX, uint256 amountY)
    {
        if (msg.sender != from && !isApprovedForAll[from][msg.sender]) revert NotApproved();
        uint256 n = ids.length;
        if (n == 0 || n > MAX_BINS_PER_CALL || shares.length != n) revert InvalidLength();
        if (to == address(0) || to == address(this)) revert InvalidRecipient();
        for (uint256 i; i < n; i++) {
            (uint256 ox, uint256 oy) = _burnBin(from, ids[i], shares[i]);
            amountX += ox;
            amountY += oy;
        }
        if (amountX == 0 && amountY == 0) revert ZeroAmount();
        reserveX -= uint128(amountX);
        reserveY -= uint128(amountY);
        emit TransferBatch(msg.sender, from, address(0), ids, shares);
        emit WithdrawnFromBins(msg.sender, from, to, ids, shares, amountX, amountY);
        if (amountX != 0) _safeTransfer(tokenX, to, amountX);
        if (amountY != 0) _safeTransfer(tokenY, to, amountY);
    }

    function _burnBin(address from, int24 id, uint256 amount) private returns (uint256 ox, uint256 oy) {
        if (amount == 0) return (0, 0);
        uint256 bal = _balances[from][id];
        if (amount > bal) revert InsufficientShares(id);
        uint256 supply = totalSupply[id];
        Bin memory b = _bins[id];
        ox = DlmmMath.mulDiv(b.x, amount, supply);
        oy = DlmmMath.mulDiv(b.y, amount, supply);
        unchecked {
            _balances[from][id] = bal - amount;
        }
        totalSupply[id] = supply - amount;
        if (supply == amount) {
            // Last shares: the whole bin (ox == b.x, oy == b.y).
            delete _bins[id];
            _tree.remove(_index(id));
        } else {
            _bins[id] = Bin(b.x - uint128(ox), b.y - uint128(oy));
        }
    }

    /// While the pair holds no liquidity at all, anyone may move its active
    /// bin (the first LP sets the price; the router does this together with
    /// the first deposit and checks the active bin against the caller's).
    function setActiveIdWhileEmpty(int24 id) external lock {
        if (reserveX != 0 || reserveY != 0) revert NotEmpty();
        DlmmMath.getPriceX128(id, binStep);
        State memory s = _state;
        s.activeId = id;
        s.idReference = id;
        s.volatilityAccumulator = 0;
        s.volatilityReference = 0;
        _state = s;
        emit ActiveIdSet(id);
    }

    // =====================================================================
    // Shares (internal ERC-1155-like ledger; no receiver callbacks, by design)
    // =====================================================================

    function setApprovalForAll(address operator, bool approved) external {
        isApprovedForAll[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function batchTransferFrom(address from, address to, int24[] calldata ids, uint256[] calldata amounts) external {
        if (msg.sender != from && !isApprovedForAll[from][msg.sender]) revert NotApproved();
        if (to == address(0) || to == address(this)) revert InvalidRecipient();
        uint256 n = ids.length;
        if (n > MAX_BINS_PER_CALL || amounts.length != n) revert InvalidLength();
        for (uint256 i; i < n; i++) {
            uint256 bal = _balances[from][ids[i]];
            if (amounts[i] > bal) revert InsufficientShares(ids[i]);
            unchecked {
                _balances[from][ids[i]] = bal - amounts[i];
            }
            _balances[to][ids[i]] += amounts[i];
        }
        emit TransferBatch(msg.sender, from, to, ids, amounts);
    }

    // =====================================================================
    // Protocol fee, skim, factory
    // =====================================================================

    /// Sends the protocol fees to the factory's feeTo (anyone may call; the recipient is fixed).
    function collectProtocolFees() external lock returns (uint256 amountX, uint256 amountY) {
        address to = IDlmmFactoryForPair(factory).feeTo();
        if (to == address(0)) revert FeeToNotSet();
        (amountX, amountY) = (protocolFeesX, protocolFeesY);
        protocolFeesX = 0;
        protocolFeesY = 0;
        if (amountX != 0) _safeTransfer(tokenX, to, amountX);
        if (amountY != 0) _safeTransfer(tokenY, to, amountY);
        emit ProtocolFeesCollected(to, amountX, amountY);
    }

    /// Sends whatever the pair holds above its accounting (e.g. tokens sent by mistake) to `to`.
    function skim(address to) external lock {
        if (to == address(0) || to == address(this)) revert InvalidRecipient();
        uint256 ex = _received(tokenX, true);
        uint256 ey = _received(tokenY, false);
        if (ex != 0) _safeTransfer(tokenX, to, ex);
        if (ey != 0) _safeTransfer(tokenY, to, ey);
        emit Skimmed(to, ex, ey);
    }

    function setProtocolShare(uint16 shareBps) external {
        if (msg.sender != factory) revert NotFactory();
        if (shareBps > MAX_PROTOCOL_SHARE_BPS) revert ShareTooHigh();
        if (_unlocked != 1) revert Locked();
        _state.protocolShareBps = shareBps;
        emit ProtocolShareSet(shareBps);
    }

    // =====================================================================
    // Internals
    // =====================================================================

    function _index(int24 id) private pure returns (uint256) {
        return uint256(int256(id) + int256(ID_OFFSET));
    }

    function _id(uint256 index) private pure returns (int24) {
        return int24(int256(index) - int256(ID_OFFSET));
    }

    function _u128(uint256 v) private pure returns (uint128) {
        if (v > type(uint128).max) revert Overflow();
        return uint128(v);
    }

    /// Balance above what the pair accounts for (reserves + protocol fees).
    function _received(address token, bool isX) private view returns (uint256) {
        uint256 bal = IERC20DlmmPair(token).balanceOf(address(this));
        uint256 tracked = isX ? uint256(reserveX) + protocolFeesX : uint256(reserveY) + protocolFeesY;
        return bal > tracked ? bal - tracked : 0;
    }

    function _checkSolvent(address token, bool isX) private view {
        uint256 tracked = isX ? uint256(reserveX) + protocolFeesX : uint256(reserveY) + protocolFeesY;
        if (IERC20DlmmPair(token).balanceOf(address(this)) < tracked) revert BalanceBelowReserves();
    }

    /// transfer(), accepting tokens that return nothing but not ones that return false.
    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }
}

/// Holds the pair's init code so the factory stays under the EIP-170 size
/// limit. Created by the factory in its constructor; only that factory may
/// deploy pairs through it. pair = CREATE2(deployer, salt, PAIR_CODE_HASH).
contract ZetaphyDlmmPairDeployer {
    address public immutable factory;
    DlmmPairParameters private _params;

    error NotFactory();

    constructor() {
        factory = msg.sender;
    }

    /// keccak256 of ZetaphyDlmmPair's init code (computed here, at run time,
    /// so the init code is stored once).
    function PAIR_CODE_HASH() external pure returns (bytes32) {
        return keccak256(type(ZetaphyDlmmPair).creationCode);
    }

    /// Read by a new pair's constructor (only set during deploy).
    function pairParameters() external view returns (DlmmPairParameters memory) {
        return _params;
    }

    function deploy(bytes32 salt, DlmmPairParameters calldata p) external returns (address pair) {
        if (msg.sender != factory) revert NotFactory();
        _params = p;
        pair = address(new ZetaphyDlmmPair{salt: salt}());
        delete _params;
    }
}

contracts/dlmm/ZetaphyDlmmRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ============================================================================
// UNAUDITED. ZETAPHY DLMM router, testnet only.
// ============================================================================
//
// What users call: add / remove liquidity across a range of bins, and swap
// (exact in or exact out, one or more hops through DLMM pairs), each with a
// deadline and the caller's slippage limits. "NATIVE" in a name means the
// chain's coin, wrapped through WNATIVE (on ZETAPHY the native ERC-20
// precompile 0xEeee…EEeE, elsewhere WZETAPHY), exactly as ZetaphyRouter does.
//
//   - Liquidity: bins are given RELATIVE to the active bin (deltaIds), with
//     an explicit amount of X and Y for each (the distribution shape is the
//     client's choice, as in dlmm.rs). activeIdDesired + idSlippage bound how
//     far the price may have moved; amountXMin / amountYMin bound what is
//     actually deposited (a bin only takes amounts in its own ratio; the rest
//     comes back). A pair with no liquidity at all gets its active bin set to
//     activeIdDesired first: the first LP sets the price.
//   - Removing needs pair.setApprovalForAll(router, true) (the pair's share
//     ledger); amountXMin / amountYMin bound the result.
//   - Fee-on-transfer tokens are refused: what the router sends into a pair
//     must arrive in full (FeeOnTransferNotSupported). Rebasing tokens are
//     not supported either.
//   - Neuro: like ZetaphyRouter, with factory.threatRegistry() set the router
//     refuses to swap INTO, or add liquidity with, a token whose flag is
//     enforced (TokenEnforced); it fails closed (RegistryUnavailable).
//     Selling and removing liquidity never ask the registry.
//   - The router holds no funds between calls.

interface IDlmmFactoryR {
    function getPair(address, address, uint16) external view returns (address);
    function createPair(address, address, uint16, int24) external returns (address);
    function threatRegistry() external view returns (address);
    function governance() external view returns (address);
    function PAIR_CODE_HASH() external view returns (bytes32);
    function pairDeployer() external view returns (address);
}

interface IDlmmPairR {
    function tokenX() external view returns (address);
    function getActiveId() external view returns (int24);
    function reserveX() external view returns (uint128);
    function reserveY() external view returns (uint128);
    function setActiveIdWhileEmpty(int24 id) external;
    function swap(bool swapForY, address to) external returns (uint256);
    function mint(address to, int24[] calldata ids, uint256[] calldata amountsX, uint256[] calldata amountsY, address refundTo)
        external returns (uint256, uint256, uint256[] memory);
    function burn(address from, address to, int24[] calldata ids, uint256[] calldata shares) external returns (uint256, uint256);
    function getSwapIn(uint256 amountOut, bool swapForY) external view returns (uint256, uint256, uint256);
    function getSwapOut(uint256 amountIn, bool swapForY) external view returns (uint256, uint256, uint256);
}

interface IWNativeR {
    function deposit() external payable;
    function withdraw(uint256) external;
}

interface IERC20R {
    function balanceOf(address) external view returns (uint256);
}

interface IThreatViewR {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

contract ZetaphyDlmmRouter {
    address public immutable factory;
    address public immutable WNATIVE;
    address private immutable pairDeployer;
    bytes32 private immutable pairCodeHash;

    /// Gas given to each ThreatRegistry query (same as ZetaphyRouter).
    uint256 public constant REGISTRY_GAS = 100_000;

    struct LiquidityParams {
        address tokenX; // the lower address of the two
        address tokenY;
        uint16 binStep;
        int24 activeIdDesired;
        uint24 idSlippage;
        int24[] deltaIds; // strictly increasing, relative to the active bin
        uint256[] amountsX;
        uint256[] amountsY;
        uint256 amountXMin;
        uint256 amountYMin;
        address to;
        uint256 deadline;
    }

    /// tokens[i] -> tokens[i+1] through the pair with binSteps[i].
    struct Path {
        uint16[] binSteps;
        address[] tokens;
    }

    error Expired();
    error InvalidPath();
    error UnsortedTokens();
    error InvalidLength();
    error IdSlippage(int24 activeId);
    error IdOutOfRange();
    error InsufficientXAmount();
    error InsufficientYAmount();
    error InsufficientOutputAmount();
    error ExcessiveInputAmount();
    error InsufficientLiquidity();
    error FeeOnTransferNotSupported();
    error PairNotFound();
    error ZeroAddress();
    error TransferFailed();
    error NativeTransferFailed();
    error OnlyWNative();
    error NotGovernance();
    error WrongNativeAmount();
    error TokenEnforced(address token, uint8 reason);
    error RegistryUnavailable();

    event Swept(address indexed to, uint256 amount);

    modifier ensure(uint256 deadline) {
        if (deadline < block.timestamp) revert Expired();
        _;
    }

    constructor(address factory_, address wnative) {
        if (factory_ == address(0) || wnative == address(0)) revert ZeroAddress();
        factory = factory_;
        WNATIVE = wnative;
        pairCodeHash = IDlmmFactoryR(factory_).PAIR_CODE_HASH();
        pairDeployer = IDlmmFactoryR(factory_).pairDeployer();
    }

    /// Native coins only come from WZETAPHY.withdraw (the precompile moves them without a call).
    receive() external payable {
        if (msg.sender != WNATIVE) revert OnlyWNative();
    }

    /// Governance only: sends the router's whole native balance to `to` (coins that reached it by mistake).
    function sweep(address to) external {
        if (msg.sender != IDlmmFactoryR(factory).governance()) revert NotGovernance();
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = address(this).balance;
        _sendNative(to, amount);
        emit Swept(to, amount);
    }

    // =====================================================================
    // Views
    // =====================================================================

    /// The pair's CREATE2 address (it may not exist yet).
    function pairFor(address tokenA, address tokenB, uint16 binStep) public view returns (address) {
        (address x, address y) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        return address(uint160(uint256(keccak256(abi.encodePacked(
            hex"ff", pairDeployer, keccak256(abi.encodePacked(x, y, binStep)), pairCodeHash)))));
    }

    /// Outputs of every hop for an exact input (reverts if a pair lacks liquidity).
    function getAmountsOut(uint256 amountIn, Path calldata path) public view returns (uint256[] memory amounts) {
        address[] memory pairs = _pairs(path);
        amounts = new uint256[](path.tokens.length);
        amounts[0] = amountIn;
        for (uint256 i; i < pairs.length; i++) {
            (uint256 left, uint256 out,) = IDlmmPairR(pairs[i]).getSwapOut(amounts[i], path.tokens[i] < path.tokens[i + 1]);
            if (left != 0) revert InsufficientLiquidity();
            amounts[i + 1] = out;
        }
    }

    /// Inputs of every hop for an exact output (reverts if a pair lacks liquidity).
    function getAmountsIn(uint256 amountOut, Path calldata path) public view returns (uint256[] memory amounts) {
        address[] memory pairs = _pairs(path);
        amounts = new uint256[](path.tokens.length);
        amounts[amounts.length - 1] = amountOut;
        for (uint256 i = pairs.length; i > 0; i--) {
            (uint256 inNeeded, uint256 outLeft,) = IDlmmPairR(pairs[i - 1]).getSwapIn(amounts[i], path.tokens[i - 1] < path.tokens[i]);
            if (outLeft != 0) revert InsufficientLiquidity();
            amounts[i - 1] = inNeeded;
        }
    }

    // =====================================================================
    // Liquidity
    // =====================================================================

    function addLiquidity(LiquidityParams calldata p)
        external ensure(p.deadline) returns (uint256 usedX, uint256 usedY, int24[] memory ids, uint256[] memory shares)
    {
        (address pair, uint256 sumX, uint256 sumY) = _prepareAdd(p);
        ids = _absoluteIds(pair, p);
        _pay(p.tokenX, msg.sender, pair, sumX);
        _pay(p.tokenY, msg.sender, pair, sumY);
        (usedX, usedY, shares) = IDlmmPairR(pair).mint(p.to, ids, p.amountsX, p.amountsY, msg.sender);
        _checkMins(p, usedX, usedY);
    }

    /// One of tokenX / tokenY must be WNATIVE; msg.value must equal that
    /// side's sum. What the bins did not take comes back as native.
    function addLiquidityNATIVE(LiquidityParams calldata p)
        external payable ensure(p.deadline) returns (uint256 usedX, uint256 usedY, int24[] memory ids, uint256[] memory shares)
    {
        bool nativeIsX = p.tokenX == WNATIVE;
        if (!nativeIsX && p.tokenY != WNATIVE) revert InvalidPath();
        address pair;
        (pair, ids) = _fundNative(p, nativeIsX);
        (usedX, usedY, shares) = _mintAndRefund(pair, p, ids, nativeIsX ? p.tokenY : p.tokenX);
    }

    function _fundNative(LiquidityParams calldata p, bool nativeIsX) private returns (address pair, int24[] memory ids) {
        uint256 sumX;
        uint256 sumY;
        (pair, sumX, sumY) = _prepareAdd(p);
        ids = _absoluteIds(pair, p);
        if (msg.value != (nativeIsX ? sumX : sumY)) revert WrongNativeAmount();
        _pay(nativeIsX ? p.tokenY : p.tokenX, msg.sender, pair, nativeIsX ? sumY : sumX);
        _wrapTo(pair, msg.value);
    }

    /// Mints with the router as refund recipient, then passes the refunds on (native as native).
    function _mintAndRefund(address pair, LiquidityParams calldata p, int24[] memory ids, address token)
        private returns (uint256 usedX, uint256 usedY, uint256[] memory shares)
    {
        uint256 tokenBefore = IERC20R(token).balanceOf(address(this));
        uint256 nativeBefore = IERC20R(WNATIVE).balanceOf(address(this));
        (usedX, usedY, shares) = IDlmmPairR(pair).mint(p.to, ids, p.amountsX, p.amountsY, address(this));
        _checkMins(p, usedX, usedY);
        uint256 tokenBack = IERC20R(token).balanceOf(address(this)) - tokenBefore;
        uint256 nativeBack = IERC20R(WNATIVE).balanceOf(address(this)) - nativeBefore;
        if (tokenBack != 0) _safeTransfer(token, msg.sender, tokenBack);
        if (nativeBack != 0) {
            IWNativeR(WNATIVE).withdraw(nativeBack);
            _sendNative(msg.sender, nativeBack);
        }
    }

    function removeLiquidity(
        address tokenX, address tokenY, uint16 binStep, int24[] calldata ids, uint256[] calldata shares,
        uint256 amountXMin, uint256 amountYMin, address to, uint256 deadline
    ) external ensure(deadline) returns (uint256 amountX, uint256 amountY) {
        if (tokenX >= tokenY) revert UnsortedTokens();
        (amountX, amountY) = IDlmmPairR(_existing(tokenX, tokenY, binStep)).burn(msg.sender, to, ids, shares);
        if (amountX < amountXMin) revert InsufficientXAmount();
        if (amountY < amountYMin) revert InsufficientYAmount();
    }

    /// `token` is the other token of a pair with WNATIVE; amounts in the token / native order.
    function removeLiquidityNATIVE(
        address token, uint16 binStep, int24[] calldata ids, uint256[] calldata shares,
        uint256 amountTokenMin, uint256 amountNativeMin, address payable to, uint256 deadline
    ) external ensure(deadline) returns (uint256 amountToken, uint256 amountNative) {
        (amountToken, amountNative) = _burnToRouter(token, binStep, ids, shares);
        if (amountToken < amountTokenMin || amountNative < amountNativeMin) revert InsufficientOutputAmount();
        if (amountToken != 0) _safeTransfer(token, to, amountToken);
        if (amountNative != 0) {
            IWNativeR(WNATIVE).withdraw(amountNative);
            _sendNative(to, amountNative);
        }
    }

    function _burnToRouter(address token, uint16 binStep, int24[] calldata ids, uint256[] calldata shares)
        private returns (uint256 amountToken, uint256 amountNative)
    {
        (uint256 ax, uint256 ay) = IDlmmPairR(_existing(token, WNATIVE, binStep)).burn(msg.sender, address(this), ids, shares);
        (amountToken, amountNative) = token < WNATIVE ? (ax, ay) : (ay, ax);
    }

    // =====================================================================
    // Swaps
    // =====================================================================

    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, Path calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256 amountOut)
    {
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        _pay(path.tokens[0], msg.sender, pairs[0], amountIn);
        amountOut = _swapChain(pairs, path.tokens, to);
        if (amountOut < amountOutMin) revert InsufficientOutputAmount();
    }

    function swapTokensForExactTokens(uint256 amountOut, uint256 amountInMax, Path calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256 amountIn)
    {
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        amountIn = getAmountsIn(amountOut, path)[0];
        if (amountIn > amountInMax) revert ExcessiveInputAmount();
        _pay(path.tokens[0], msg.sender, pairs[0], amountIn);
        if (_swapChain(pairs, path.tokens, to) < amountOut) revert InsufficientOutputAmount();
    }

    function swapExactNATIVEForTokens(uint256 amountOutMin, Path calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256 amountOut)
    {
        if (path.tokens[0] != WNATIVE) revert InvalidPath();
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        _wrapTo(pairs[0], msg.value);
        amountOut = _swapChain(pairs, path.tokens, to);
        if (amountOut < amountOutMin) revert InsufficientOutputAmount();
    }

    /// msg.value is the most native coin to spend; the rest is refunded.
    function swapNATIVEForExactTokens(uint256 amountOut, Path calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256 amountIn)
    {
        if (path.tokens[0] != WNATIVE) revert InvalidPath();
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        amountIn = getAmountsIn(amountOut, path)[0];
        if (amountIn > msg.value) revert ExcessiveInputAmount();
        _wrapTo(pairs[0], amountIn);
        if (_swapChain(pairs, path.tokens, to) < amountOut) revert InsufficientOutputAmount();
        if (msg.value > amountIn) _sendNative(msg.sender, msg.value - amountIn);
    }

    function swapExactTokensForNATIVE(uint256 amountIn, uint256 amountOutMin, Path calldata path, address payable to, uint256 deadline)
        external ensure(deadline) returns (uint256 amountOut)
    {
        if (path.tokens[path.tokens.length - 1] != WNATIVE) revert InvalidPath();
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        _pay(path.tokens[0], msg.sender, pairs[0], amountIn);
        amountOut = _swapChain(pairs, path.tokens, address(this));
        if (amountOut < amountOutMin) revert InsufficientOutputAmount();
        IWNativeR(WNATIVE).withdraw(amountOut);
        _sendNative(to, amountOut);
    }

    function swapTokensForExactNATIVE(uint256 amountOut, uint256 amountInMax, Path calldata path, address payable to, uint256 deadline)
        external ensure(deadline) returns (uint256 amountIn)
    {
        if (path.tokens[path.tokens.length - 1] != WNATIVE) revert InvalidPath();
        address[] memory pairs = _pairs(path);
        _checkPath(path.tokens);
        amountIn = getAmountsIn(amountOut, path)[0];
        if (amountIn > amountInMax) revert ExcessiveInputAmount();
        _pay(path.tokens[0], msg.sender, pairs[0], amountIn);
        uint256 got = _swapChain(pairs, path.tokens, address(this));
        if (got < amountOut) revert InsufficientOutputAmount();
        IWNativeR(WNATIVE).withdraw(got);
        _sendNative(to, got);
    }

    // =====================================================================
    // Internals
    // =====================================================================

    function _prepareAdd(LiquidityParams calldata p) private returns (address pair, uint256 sumX, uint256 sumY) {
        if (p.tokenX >= p.tokenY) revert UnsortedTokens();
        uint256 n = p.deltaIds.length;
        if (n == 0 || p.amountsX.length != n || p.amountsY.length != n) revert InvalidLength();
        _checkToken(p.tokenX);
        _checkToken(p.tokenY);
        pair = IDlmmFactoryR(factory).getPair(p.tokenX, p.tokenY, p.binStep);
        if (pair == address(0)) pair = IDlmmFactoryR(factory).createPair(p.tokenX, p.tokenY, p.binStep, p.activeIdDesired);
        // No liquidity yet: the first LP sets the price (atomically, with the deposit below).
        if (IDlmmPairR(pair).reserveX() == 0 && IDlmmPairR(pair).reserveY() == 0 && IDlmmPairR(pair).getActiveId() != p.activeIdDesired) {
            IDlmmPairR(pair).setActiveIdWhileEmpty(p.activeIdDesired);
        }
        for (uint256 i; i < n; i++) {
            sumX += p.amountsX[i];
            sumY += p.amountsY[i];
        }
    }

    function _absoluteIds(address pair, LiquidityParams calldata p) private view returns (int24[] memory ids) {
        int256 active = IDlmmPairR(pair).getActiveId();
        int256 diff = active - p.activeIdDesired;
        if (diff > int256(uint256(p.idSlippage)) || -diff > int256(uint256(p.idSlippage))) revert IdSlippage(int24(active));
        uint256 n = p.deltaIds.length;
        ids = new int24[](n);
        for (uint256 i; i < n; i++) {
            int256 id = active + p.deltaIds[i];
            if (id > type(int24).max || id < type(int24).min) revert IdOutOfRange();
            ids[i] = int24(id);
        }
    }

    function _checkMins(LiquidityParams calldata p, uint256 usedX, uint256 usedY) private pure {
        if (usedX < p.amountXMin) revert InsufficientXAmount();
        if (usedY < p.amountYMin) revert InsufficientYAmount();
    }

    function _existing(address tokenA, address tokenB, uint16 binStep) private view returns (address pair) {
        pair = IDlmmFactoryR(factory).getPair(tokenA, tokenB, binStep);
        if (pair == address(0)) revert PairNotFound();
    }

    /// The pairs along `path` (computed with CREATE2; each must exist).
    function _pairs(Path calldata path) private view returns (address[] memory pairs) {
        uint256 n = path.binSteps.length;
        if (n == 0 || path.tokens.length != n + 1) revert InvalidPath();
        pairs = new address[](n);
        for (uint256 i; i < n; i++) {
            if (path.tokens[i] == path.tokens[i + 1]) revert InvalidPath();
            pairs[i] = pairFor(path.tokens[i], path.tokens[i + 1], path.binSteps[i]);
            if (pairs[i].code.length == 0) revert PairNotFound();
        }
    }

    /// Runs the hops; each pair sends its output straight to the next pair.
    /// Returns what `to` actually received of the last token.
    function _swapChain(address[] memory pairs, address[] calldata tokens, address to) private returns (uint256 received) {
        address last = tokens[tokens.length - 1];
        uint256 before = IERC20R(last).balanceOf(to);
        uint256 n = pairs.length;
        for (uint256 i; i < n; i++) {
            IDlmmPairR(pairs[i]).swap(tokens[i] < tokens[i + 1], i + 1 < n ? pairs[i + 1] : to);
        }
        received = IERC20R(last).balanceOf(to) - before;
    }

    // ---- Neuro ----

    function _checkToken(address token) private view {
        address registry = IDlmmFactoryR(factory).threatRegistry();
        if (registry != address(0)) _refuseEnforced(registry, token);
    }

    /// Every token a swap along `tokens` receives into a pool or hands out; not the one sold.
    function _checkPath(address[] calldata tokens) private view {
        address registry = IDlmmFactoryR(factory).threatRegistry();
        if (registry == address(0)) return;
        for (uint256 i = 1; i < tokens.length; i++) _refuseEnforced(registry, tokens[i]);
    }

    function _refuseEnforced(address registry, address token) private view {
        if (token == WNATIVE) return;
        (bool ok, bytes memory r) = registry.staticcall{gas: REGISTRY_GAS}(abi.encodeCall(IThreatViewR.isContractEnforced, (token)));
        if (!ok || r.length < 64) revert RegistryUnavailable();
        (bool enforced, uint8 reason) = abi.decode(r, (bool, uint8));
        if (enforced) revert TokenEnforced(token, reason);
    }

    // ---- transfers ----

    /// transferFrom(from -> pair) that must arrive in full (no fee-on-transfer).
    function _pay(address token, address from, address pair, uint256 amount) private {
        if (amount == 0) return;
        uint256 before = IERC20R(token).balanceOf(pair);
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, pair, amount));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
        if (IERC20R(token).balanceOf(pair) - before != amount) revert FeeOnTransferNotSupported();
    }

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _sendNative(address to, uint256 value) private {
        (bool ok,) = to.call{value: value}("");
        if (!ok) revert NativeTransferFailed();
    }

    /// Wraps `amount` of the native coin and sends it to `pair`.
    function _wrapTo(address pair, uint256 amount) private {
        if (amount == 0) return;
        IWNativeR(WNATIVE).deposit{value: amount}();
        _safeTransfer(WNATIVE, pair, amount);
    }
}

contracts/test/DexTestHelpers.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// Contracts used only by the unit tests (never deployed by cli.js).

interface IPairT {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function swap(uint256, uint256, address, bytes calldata) external;
    function sync() external;
    function skim(address) external;
    function mint(address) external returns (uint256);
    function burn(address) external returns (uint256, uint256);
    function getReserves() external view returns (uint112, uint112, uint32);
}

interface IERC20T {
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

/// A flash borrower: takes the output, then pays back `repayBps` of what it
/// must (10000 = exactly enough with the 0.3% fee) in the borrowed token.
contract FlashBorrower {
    uint256 public repayBps = 10_000;
    address public lastSender;
    function setRepayBps(uint256 b) external { repayBps = b; }

    function borrow(address pair, uint256 amount0Out, uint256 amount1Out) external {
        IPairT(pair).swap(amount0Out, amount1Out, address(this), abi.encode(pair));
    }

    function zetaphyDexCall(address sender, uint256 amount0Out, uint256 amount1Out, bytes calldata data) external {
        address pair = abi.decode(data, (address));
        require(msg.sender == pair, "not pair");
        lastSender = sender;
        if (amount0Out > 0) _repay(IPairT(pair).token0(), pair, amount0Out);
        if (amount1Out > 0) _repay(IPairT(pair).token1(), pair, amount1Out);
    }

    function _repay(address token, address pair, uint256 out) private {
        // Same-token repayment: (balance*1000 - in*3) >= reserve*1000 needs in >= out*1000/997.
        uint256 owed = (out * 1000) / 997 + 1;
        IERC20T(token).transfer(pair, (owed * repayBps) / 10_000);
    }
}

/// An ERC-20 whose transfer can call back into a pair (a hostile token): every
/// entry point of the pair must refuse with Locked() while one is running.
contract ReentrantToken {
    string public constant name = "Reentrant";
    string public constant symbol = "RE";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    address public pair;
    uint8 public mode; // 0 off, 1 swap, 2 sync, 3 skim, 4 mint, 5 burn
    bytes public lastRevert;
    uint256 public attempts;

    event Transfer(address indexed from, address indexed to, uint256 value);

    constructor(uint256 supply) { totalSupply = supply; balanceOf[msg.sender] = supply; }
    function arm(address p, uint8 m) external { pair = p; mode = m; }

    function approve(address s, uint256 v) external returns (bool) { allowance[msg.sender][s] = v; return true; }
    function transfer(address to, uint256 v) external returns (bool) { _move(msg.sender, to, v); return true; }
    function transferFrom(address f, address to, uint256 v) external returns (bool) {
        if (allowance[f][msg.sender] != type(uint256).max) allowance[f][msg.sender] -= v;
        _move(f, to, v);
        return true;
    }

    function _move(address f, address to, uint256 v) private {
        balanceOf[f] -= v;
        balanceOf[to] += v;
        emit Transfer(f, to, v);
        if (mode != 0 && msg.sender == pair) {
            uint8 m = mode;
            mode = 0; // once
            attempts++;
            bytes memory call;
            if (m == 1) call = abi.encodeCall(IPairT.swap, (1, 0, address(this), ""));
            else if (m == 2) call = abi.encodeCall(IPairT.sync, ());
            else if (m == 3) call = abi.encodeCall(IPairT.skim, (address(this)));
            else if (m == 4) call = abi.encodeCall(IPairT.mint, (address(this)));
            else call = abi.encodeCall(IPairT.burn, (address(this)));
            (bool ok, bytes memory r) = pair.call(call);
            require(!ok, "reentered");
            lastRevert = r;
        }
    }
}

/// Stands in for NeuroJobs' runner list (ThreatRegistry asks it who may vote).
contract MockRunners {
    mapping(address => bool) public on;
    function set(address a, bool v) external { on[a] = v; }
    function workers(address a) external view returns (uint128, uint64, bool, uint32, uint32) { return (100, 0, on[a], on[a] ? 5 : 0, 0); }
}

/// Checks that a reverted call leaves native balances exactly as they were
/// (security note S1: the DEX trusts the native ERC-20 precompile's balances,
/// so the chain must undo precompile transfers made inside a reverting call).
/// probe() runs `calls` inside a sub-call (this.run). With undo = true the
/// sub-call always reverts at the end (Undo, or Failed(i, data) if a call
/// failed first); with undo = false it keeps the calls' effects (only a failed
/// call reverts it). The balances of `watch` and of this contract, read both as
/// address.balance and through `wnative`.balanceOf, are reported in Probed; the
/// rest of this contract's native balance goes back to the caller at the end.
contract RevertProbe {
    struct Call { address target; uint256 value; bytes data; }
    struct Balances { uint256 watchNative; uint256 watchWrapped; uint256 selfNative; uint256 selfWrapped; }

    error Undo();
    error Failed(uint256 index, bytes data);
    error RefundFailed();

    event Probed(Balances before, Balances afterwards, bool reverted, bytes revertData);

    function _balances(address wnative, address watch) private view returns (Balances memory b) {
        b.watchNative = watch.balance;
        b.watchWrapped = IERC20T(wnative).balanceOf(watch);
        b.selfNative = address(this).balance;
        b.selfWrapped = IERC20T(wnative).balanceOf(address(this));
    }

    function probe(Call[] calldata calls, bool undo, address wnative, address watch)
        external payable returns (Balances memory before, Balances memory afterwards, bool reverted, bytes memory revertData)
    {
        before = _balances(wnative, watch);
        try this.run(calls, undo) {
            reverted = false;
        } catch (bytes memory r) {
            reverted = true;
            revertData = r;
        }
        afterwards = _balances(wnative, watch);
        emit Probed(before, afterwards, reverted, revertData);
        (bool ok,) = msg.sender.call{value: address(this).balance}("");
        if (!ok) revert RefundFailed();
    }

    function run(Call[] calldata calls, bool undo) external {
        require(msg.sender == address(this), "self only");
        for (uint256 i; i < calls.length; i++) {
            (bool ok, bytes memory r) = calls[i].target.call{value: calls[i].value}(calls[i].data);
            if (!ok) revert Failed(i, r);
        }
        if (undo) revert Undo();
    }

    receive() external payable {}
}

/// A registry stand-in that answers "not enforced" after burning `burn` gas:
/// with burn above the router's REGISTRY_GAS it stops answering in time, and
/// the router fails closed (RegistryUnavailable).
contract GasHogRegistry {
    uint256 public burn;
    function setBurn(uint256 b) external { burn = b; }
    function isContractEnforced(address) external view returns (bool, uint8) {
        uint256 start = gasleft();
        uint256 x;
        while (start - gasleft() < burn) x++;
        return (false, 0);
    }
}

/// Sends its value to `to` without calling it (SELFDESTRUCT in the
/// constructor), the way stray native coins can reach the router.
contract ForceSend {
    constructor(address payable to) payable {
        selfdestruct(to);
    }
}

